--
-- Name: automation_recommendations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_recommendations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    domain text NOT NULL,
    kind text NOT NULL,
    tier text DEFAULT 'recommend'::text NOT NULL,
    severity text DEFAULT 'info'::text NOT NULL,
    title text NOT NULL,
    detail text,
    drill_route text,
    dedupe_key text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    resolved_reason text,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    first_detected_at timestamp with time zone DEFAULT now() NOT NULL,
    last_detected_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automation_recommendations_domain_check CHECK ((domain = ANY (ARRAY['growth'::text, 'revenue'::text, 'delivery'::text, 'voice'::text, 'wl'::text, 'system'::text]))),
    CONSTRAINT automation_recommendations_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'notice'::text, 'warn'::text, 'critical'::text]))),
    CONSTRAINT automation_recommendations_status_check CHECK ((status = ANY (ARRAY['open'::text, 'dismissed'::text, 'resolved'::text]))),
    CONSTRAINT automation_recommendations_tier_check CHECK ((tier = ANY (ARRAY['detect'::text, 'recommend'::text, 'confirm'::text, 'auto_safe'::text])))
);


--
-- Name: dismiss_recommendation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_recommendation(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS public.automation_recommendations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.automation_recommendations;
BEGIN
  IF NOT public.has_role(auth.uid(),'admin'::app_role) THEN
    RAISE EXCEPTION 'admin required';
  END IF;
  UPDATE public.automation_recommendations
     SET status='dismissed', resolved_at=now(), resolved_by=auth.uid(),
         resolved_reason=COALESCE(p_reason,'dismissed_by_admin')
   WHERE id=p_id RETURNING * INTO r;
  IF NOT FOUND THEN RAISE EXCEPTION 'recommendation not found'; END IF;
  INSERT INTO public.audit_log (actor_id,action,target_table,target_id,metadata)
  VALUES (auth.uid(),'automation.recommendation.dismissed','automation_recommendations',p_id::text,
          jsonb_build_object('reason',p_reason,'dedupe_key',r.dedupe_key,'domain',r.domain));
  INSERT INTO public.dashboard_events (event_name,surface,persona,user_id,properties)
  VALUES ('automation.recommendation.dismissed','mission_control','admin',auth.uid(),
          jsonb_build_object('id',p_id,'dedupe_key',r.dedupe_key,'domain',r.domain));
  RETURN r;
END; $$;


--
-- Name: dispatch_approval_sla_breaches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_approval_sla_breaches() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_count int := 0;
BEGIN
  FOR r IN
    SELECT id FROM approval_requests
    WHERE status = 'pending'
      AND sla_notified_at IS NULL
      AND requested_at <= now() - make_interval(hours => COALESCE(sla_hours_snapshot, 24))
    ORDER BY requested_at ASC
    LIMIT 200
  LOOP
    PERFORM public.fire_approval_notification(r.id, 'approval_sla_breach');
    UPDATE approval_requests SET sla_notified_at = now() WHERE id = r.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('breaches_notified', v_count, 'ran_at', now());
END $$;


--
-- Name: disposition_bucket(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disposition_bucket(_disposition text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _disposition IS NULL OR LENGTH(TRIM(_disposition)) = 0 THEN 'other'
    WHEN LOWER(_disposition) ~ '(resolved|completed|success|sale|booked|scheduled|answered|handled)' THEN 'resolved'
    WHEN LOWER(_disposition) ~ '(escalat|transfer|supervisor|callback requested)' THEN 'escalated'
    WHEN LOWER(_disposition) ~ '(missed|no answer|no-answer|abandon|voicemail|hang|busy|not reached)' THEN 'no_contact'
    ELSE 'other'
  END;
$$;


