    VALUES (auth.uid(), 'handoff.status.changed', 'client_onboarding_handoffs', NEW.id::text,
            jsonb_build_object('from', OLD.status, 'to', NEW.status, 'lead_id', NEW.client_lead_id));
  END IF;
  RETURN NEW;
END;
$$;


