--
-- Name: campaign_training_coverage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_training_coverage WITH (security_invoker='true') AS
 SELECT c.id AS campaign_id,
    count(DISTINCT m.id) FILTER (WHERE (m.status = 'published'::text)) AS published_modules,
    count(DISTINCT m.id) FILTER (WHERE ((m.status = 'published'::text) AND m.required)) AS required_modules,
    count(DISTINCT comp.id) AS total_completions,
    count(DISTINCT so.id) AS total_signoffs,
    count(DISTINCT comp.agent_id) AS agents_started
   FROM (((public.campaigns c
     LEFT JOIN public.campaign_training_modules m ON ((m.campaign_id = c.id)))
     LEFT JOIN public.campaign_training_completions comp ON ((comp.module_id = m.id)))
     LEFT JOIN public.campaign_training_signoffs so ON ((so.completion_id = comp.id)))
  GROUP BY c.id;


--
-- Name: campaign_go_live_checks; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_go_live_checks WITH (security_invoker='true') AS
 WITH fresh_signoffs AS (
         SELECT s.campaign_id,
            (count(*))::integer AS total
           FROM public.campaign_training_signoffs s
          WHERE ((COALESCE(s.needs_refresh, false) = false) AND ((s.expires_at IS NULL) OR (s.expires_at > now())))
          GROUP BY s.campaign_id
        )
 SELECT c.id AS campaign_id,
    c.client_department_id,
    ((EXISTS ( SELECT 1
           FROM public.campaign_script_documents d
          WHERE ((d.campaign_id = c.id) AND (d.status = 'published'::text)))) OR (c.published_version_id IS NOT NULL)) AS script_published,
    COALESCE(( SELECT (count(*))::integer AS count
           FROM public.campaign_faq_entries f
          WHERE ((f.status = 'approved'::text) AND ((f.client_department_id = c.client_department_id) OR (f.scope = 'global'::text) OR ((f.scope = 'tenant'::text) AND (f.tenant_kind = c.tenant_kind))))), 0) AS faqs_approved_count,
    COALESCE(( SELECT (count(*))::integer AS count
           FROM public.campaign_policy_blocks p
          WHERE ((p.status = 'approved'::text) AND ((p.client_department_id = c.client_department_id) OR (p.scope = 'global'::text) OR ((p.scope = 'tenant'::text) AND (p.tenant_kind = c.tenant_kind))))), 0) AS policies_approved_count,
    (COALESCE(tc.required_modules, (0)::bigint))::integer AS required_modules,
    COALESCE(fs.total, 0) AS required_signoffs,
    (COALESCE(( SELECT count(*) AS count
           FROM public.campaign_faq_entries f
          WHERE ((f.status = 'approved'::text) AND ((f.client_department_id = c.client_department_id) OR (f.scope = 'global'::text) OR ((f.scope = 'tenant'::text) AND (f.tenant_kind = c.tenant_kind))))), (0)::bigint) > 0) AS faqs_ok,
    (COALESCE(( SELECT count(*) AS count
           FROM public.campaign_policy_blocks p
          WHERE ((p.status = 'approved'::text) AND ((p.client_department_id = c.client_department_id) OR (p.scope = 'global'::text) OR ((p.scope = 'tenant'::text) AND (p.tenant_kind = c.tenant_kind))))), (0)::bigint) > 0) AS policies_ok,
    ((COALESCE(tc.required_modules, (0)::bigint) = 0) OR (COALESCE(fs.total, 0) >= COALESCE(tc.required_modules, (0)::bigint))) AS training_ok,
    (((EXISTS ( SELECT 1
           FROM public.campaign_script_documents d
          WHERE ((d.campaign_id = c.id) AND (d.status = 'published'::text)))) OR (c.published_version_id IS NOT NULL)) AND (COALESCE(( SELECT count(*) AS count
           FROM public.campaign_faq_entries f
          WHERE ((f.status = 'approved'::text) AND ((f.client_department_id = c.client_department_id) OR (f.scope = 'global'::text) OR ((f.scope = 'tenant'::text) AND (f.tenant_kind = c.tenant_kind))))), (0)::bigint) > 0) AND (COALESCE(( SELECT count(*) AS count
           FROM public.campaign_policy_blocks p
          WHERE ((p.status = 'approved'::text) AND ((p.client_department_id = c.client_department_id) OR (p.scope = 'global'::text) OR ((p.scope = 'tenant'::text) AND (p.tenant_kind = c.tenant_kind))))), (0)::bigint) > 0) AND ((COALESCE(tc.required_modules, (0)::bigint) = 0) OR (COALESCE(fs.total, 0) >= COALESCE(tc.required_modules, (0)::bigint)))) AS all_ok
   FROM ((public.campaigns c
     LEFT JOIN public.campaign_training_coverage tc ON ((tc.campaign_id = c.id)))
     LEFT JOIN fresh_signoffs fs ON ((fs.campaign_id = c.id)));


