--
-- Name: campaign_training_module_quiz_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_training_module_quiz_status WITH (security_invoker='true') AS
 SELECT m.id AS module_id,
    l.id AS lesson_id,
    a.agent_id,
    bool_or(a.passed) AS passed,
    max(a.score) AS best_score
   FROM ((public.campaign_training_modules m
     JOIN public.campaign_training_lessons l ON (((l.module_id = m.id) AND (l.kind = 'quiz'::text) AND (l.required = true))))
     LEFT JOIN public.campaign_training_quiz_attempts a ON ((a.lesson_id = l.id)))
  GROUP BY m.id, l.id, a.agent_id;


