);


--
-- Name: campaign_training_signoff_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_training_signoff_status WITH (security_invoker='true') AS
 SELECT id AS signoff_id,
    module_id,
    campaign_id,
    agent_id,
    signed_off_at,
    expires_at,
    needs_refresh,
    refresh_reason,
        CASE
            WHEN COALESCE(needs_refresh, false) THEN 'needs_refresh'::text
            WHEN ((expires_at IS NOT NULL) AND (expires_at <= now())) THEN 'expired'::text
            WHEN ((expires_at IS NOT NULL) AND (expires_at <= (now() + '7 days'::interval))) THEN 'expiring_soon'::text
            ELSE 'current'::text
        END AS status
   FROM public.campaign_training_signoffs s;


