    CONSTRAINT capacity_assumptions_arpu_assumption_check CHECK ((arpu_assumption > (0)::numeric)),
    CONSTRAINT capacity_assumptions_csm_accounts_per_head_check CHECK ((csm_accounts_per_head > 0)),
