    CONSTRAINT capacity_assumptions_new_projects_per_new_account_check CHECK ((new_projects_per_new_account >= (0)::numeric)),
    CONSTRAINT capacity_assumptions_scope_check CHECK ((scope = ANY (ARRAY['direct'::text, 'wl'::text, 'both'::text]))),
    CONSTRAINT capacity_assumptions_support_tickets_per_agent_per_month_check CHECK ((support_tickets_per_agent_per_month > 0)),
    CONSTRAINT capacity_assumptions_tickets_per_account_per_month_check CHECK ((tickets_per_account_per_month >= (0)::numeric)),
