--
-- Name: five9_drift_snapshot_latest; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.five9_drift_snapshot_latest WITH (security_invoker='true') AS
 SELECT DISTINCT ON (client_department_id) id,
    tenant_kind,
    wl_partner_id,
    wl_client_id,
    client_lead_id,
    client_department_id,
    captured_at,
    source,
    drift,
    captured_by
   FROM public.five9_drift_snapshots
  WHERE (client_department_id IS NOT NULL)
  ORDER BY client_department_id, captured_at DESC;


