    wl_client_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    CONSTRAINT supervisor_assignment_exactly_one_target CHECK ((((
CASE
    WHEN (client_lead_id IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (wl_partner_id IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN (wl_client_id IS NOT NULL) THEN 1
    ELSE 0
END) = 1)),
    CONSTRAINT supervisor_assignment_kind_matches CHECK ((((tenant_kind = 'direct_24h'::public.campaign_tenant_kind) AND (client_lead_id IS NOT NULL)) OR ((tenant_kind = 'wl_partner'::public.campaign_tenant_kind) AND ((wl_partner_id IS NOT NULL) OR (wl_client_id IS NOT NULL)))))
);


