--
-- Name: v_account_delivery_360; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_account_delivery_360 WITH (security_invoker='true') AS
 SELECT l.id AS lead_id,
    l.name,
    l.company,
    l.pipeline_stage,
    i.id AS intake_id,
    i.intake_number,
    i.status AS intake_status,
    i.priority AS intake_priority,
    i.activated_at,
    h.id AS handoff_id,
    h.status AS handoff_status,
    h.checklist_template,
    ( SELECT (count(*))::integer AS count
           FROM public.campaigns c
          WHERE (c.client_lead_id = l.id)) AS campaigns_count,
    ( SELECT (count(*))::integer AS count
           FROM public.campaigns c
          WHERE ((c.client_lead_id = l.id) AND (c.status = 'live'::text))) AS live_campaigns_count,
    ( SELECT (count(*))::integer AS count
           FROM public.support_tickets st
          WHERE ((st.lead_id = l.id) AND (st.status <> ALL (ARRAY['resolved'::text, 'closed'::text])))) AS open_tickets_count
   FROM ((public.leads l
     LEFT JOIN LATERAL ( SELECT internal_fulfillment_intakes.id,
            internal_fulfillment_intakes.partner_id,
            internal_fulfillment_intakes.source_handoff_id,
            internal_fulfillment_intakes.proposal_id,
            internal_fulfillment_intakes.lead_id,
            internal_fulfillment_intakes.intake_number,
            internal_fulfillment_intakes.status,
            internal_fulfillment_intakes.priority,
            internal_fulfillment_intakes.submitted_by,
            internal_fulfillment_intakes.submitted_at,
            internal_fulfillment_intakes.received_at,
            internal_fulfillment_intakes.approved_at,
            internal_fulfillment_intakes.activated_at,
            internal_fulfillment_intakes.closed_at,
            internal_fulfillment_intakes.assigned_to,
            internal_fulfillment_intakes.snapshot_json,
            internal_fulfillment_intakes.snapshot_version,
            internal_fulfillment_intakes.created_at,
            internal_fulfillment_intakes.updated_at,
            internal_fulfillment_intakes.source,
            internal_fulfillment_intakes.client_lead_id
           FROM public.internal_fulfillment_intakes
          WHERE (internal_fulfillment_intakes.client_lead_id = l.id)
          ORDER BY internal_fulfillment_intakes.submitted_at DESC NULLS LAST
         LIMIT 1) i ON (true))
     LEFT JOIN public.client_onboarding_handoffs h ON ((h.client_lead_id = l.id)))
  WHERE (EXISTS ( SELECT 1
           FROM public.lead_conversions lc
          WHERE (lc.lead_id = l.id)));


--
-- Name: v_call_flow_receptionist_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_call_flow_receptionist_readiness WITH (security_invoker='true') AS
 SELECT d.id AS client_department_id,
    d.tenant_kind,
    d.wl_partner_id,
    d.client_lead_id,
    d.wl_client_id,
    d.client_location_id,
    COALESCE(d.display_name, d.department_name) AS flow_name,
    d.lifecycle,
    cfg.id AS config_id,
    cfg.mode,
    cfg.after_hours,
    cfg.escalation,
    cfg.enabled AS receptionist_enabled,
    cfg.last_validated_at,
    c.id AS campaign_id,
    c.status AS campaign_status,
    (c.published_version_id IS NOT NULL) AS has_published_script,
    (EXISTS ( SELECT 1
           FROM public.department_numbers dn
          WHERE ((dn.client_department_id = d.id) AND dn.active))) AS has_active_number,
        CASE
            WHEN (cfg.id IS NULL) THEN 'unconfigured'::text
            WHEN (NOT cfg.enabled) THEN 'configured_offline'::text
            WHEN (c.published_version_id IS NULL) THEN 'awaiting_script_publish'::text
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.department_numbers dn
              WHERE ((dn.client_department_id = d.id) AND dn.active)))) THEN 'awaiting_number'::text
            WHEN (c.status = 'active'::text) THEN 'live'::text
            ELSE 'ready_to_activate'::text
        END AS readiness_state
   FROM ((public.client_departments d
     LEFT JOIN public.call_flow_receptionist_configs cfg ON ((cfg.client_department_id = d.id)))
     LEFT JOIN public.campaigns c ON ((c.client_department_id = d.id)));


--
-- Name: v_account_receptionist_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_account_receptionist_status WITH (security_invoker='true') AS
 SELECT COALESCE((client_lead_id)::text, (wl_client_id)::text) AS account_key,
    client_lead_id,
    wl_client_id,
    tenant_kind,
    count(*) AS flow_count,
    count(*) FILTER (WHERE (readiness_state = 'live'::text)) AS live_count,
    count(*) FILTER (WHERE (readiness_state = 'unconfigured'::text)) AS unconfigured_count,
    count(*) FILTER (WHERE (readiness_state = ANY (ARRAY['awaiting_script_publish'::text, 'awaiting_number'::text, 'configured_offline'::text, 'ready_to_activate'::text]))) AS pending_count,
    max(last_validated_at) AS last_validated_at
   FROM public.v_call_flow_receptionist_readiness
  GROUP BY COALESCE((client_lead_id)::text, (wl_client_id)::text), client_lead_id, wl_client_id, tenant_kind;


--
-- Name: v_bi_approval_cycle_time; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_approval_cycle_time WITH (security_invoker='true') AS
 SELECT r.id AS request_id,
    r.deal_id,
    r.policy_id,
    p.name AS policy_name,
    r.tier,
    r.required_role,
    (r.status)::text AS status,
    r.reason,
    r.decision_notes,
    r.decided_by,
    prof.full_name AS decided_by_name,
    r.requested_at,
    r.decided_at,
    r.sla_hours_snapshot,
    r.estimated_discount_pct_snapshot,
    r.is_non_standard_term_snapshot,
    r.is_exception_snapshot,
    r.proposed_plan_key_snapshot,
    r.proposed_term_months_snapshot,
    d.scope AS deal_scope,
    d.deal_type,
    d.stage AS deal_stage,
    d.approval_state AS deal_approval_state,
        CASE
            WHEN (r.decided_at IS NOT NULL) THEN (EXTRACT(epoch FROM (r.decided_at - r.requested_at)) / 3600.0)
            ELSE (EXTRACT(epoch FROM (now() - r.requested_at)) / 3600.0)
        END AS hours_to_decision,
        CASE
            WHEN (r.decided_at IS NULL) THEN true
            ELSE false
        END AS is_open,
        CASE
            WHEN (r.sla_hours_snapshot IS NULL) THEN false
            WHEN (r.decided_at IS NOT NULL) THEN ((EXTRACT(epoch FROM (r.decided_at - r.requested_at)) / 3600.0) > (r.sla_hours_snapshot)::numeric)
            ELSE ((EXTRACT(epoch FROM (now() - r.requested_at)) / 3600.0) > (r.sla_hours_snapshot)::numeric)
        END AS is_sla_breached
   FROM (((public.approval_requests r
     JOIN public.renewal_expansion_deals d ON ((d.id = r.deal_id)))
     LEFT JOIN public.approval_policies p ON ((p.id = r.policy_id)))
     LEFT JOIN public.profiles prof ON ((prof.id = r.decided_by)));


--
-- Name: v_bi_approval_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_approval_funnel WITH (security_invoker='true') AS
 WITH base AS (
         SELECT v_bi_approval_cycle_time.request_id,
            v_bi_approval_cycle_time.deal_id,
            v_bi_approval_cycle_time.policy_id,
            v_bi_approval_cycle_time.policy_name,
            v_bi_approval_cycle_time.tier,
            v_bi_approval_cycle_time.required_role,
            v_bi_approval_cycle_time.status,
            v_bi_approval_cycle_time.reason,
            v_bi_approval_cycle_time.decision_notes,
            v_bi_approval_cycle_time.decided_by,
            v_bi_approval_cycle_time.decided_by_name,
            v_bi_approval_cycle_time.requested_at,
            v_bi_approval_cycle_time.decided_at,
            v_bi_approval_cycle_time.sla_hours_snapshot,
            v_bi_approval_cycle_time.estimated_discount_pct_snapshot,
            v_bi_approval_cycle_time.is_non_standard_term_snapshot,
            v_bi_approval_cycle_time.is_exception_snapshot,
            v_bi_approval_cycle_time.proposed_plan_key_snapshot,
            v_bi_approval_cycle_time.proposed_term_months_snapshot,
            v_bi_approval_cycle_time.deal_scope,
            v_bi_approval_cycle_time.deal_type,
            v_bi_approval_cycle_time.deal_stage,
            v_bi_approval_cycle_time.deal_approval_state,
            v_bi_approval_cycle_time.hours_to_decision,
            v_bi_approval_cycle_time.is_open,
            v_bi_approval_cycle_time.is_sla_breached
           FROM public.v_bi_approval_cycle_time
        )
 SELECT policy_id,
    policy_name,
    tier,
    required_role,
    deal_scope,
    deal_type,
    count(*) AS total_requests,
    count(*) FILTER (WHERE (status = 'pending'::text)) AS pending_count,
    count(*) FILTER (WHERE (status = 'approved'::text)) AS approved_count,
    count(*) FILTER (WHERE (status = 'rejected'::text)) AS rejected_count,
    count(*) FILTER (WHERE (status = 'cancelled'::text)) AS cancelled_count,
    count(*) FILTER (WHERE is_sla_breached) AS sla_breached_count,
        CASE
            WHEN (count(*) FILTER (WHERE (status = ANY (ARRAY['approved'::text, 'rejected'::text]))) > 0) THEN round(((count(*) FILTER (WHERE (status = 'approved'::text)))::numeric / (NULLIF(count(*) FILTER (WHERE (status = ANY (ARRAY['approved'::text, 'rejected'::text]))), 0))::numeric), 4)
            ELSE NULL::numeric
        END AS approval_rate,
        CASE
            WHEN (count(*) > 0) THEN round(((count(*) FILTER (WHERE is_sla_breached))::numeric / (count(*))::numeric), 4)
            ELSE NULL::numeric
        END AS sla_breach_rate,
    round(avg(hours_to_decision) FILTER (WHERE (NOT is_open)), 2) AS avg_hours_to_decision,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((hours_to_decision)::double precision)) FILTER (WHERE (NOT is_open)))::numeric, 2) AS median_hours_to_decision,
    round((percentile_cont((0.9)::double precision) WITHIN GROUP (ORDER BY ((hours_to_decision)::double precision)) FILTER (WHERE (NOT is_open)))::numeric, 2) AS p90_hours_to_decision,
    max(requested_at) AS last_requested_at,
    max(decided_at) AS last_decided_at
   FROM base
  GROUP BY policy_id, policy_name, tier, required_role, deal_scope, deal_type;


--
-- Name: v_bi_approval_requests; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_approval_requests WITH (security_invoker='true') AS
 SELECT ar.id,
    ar.deal_id,
    ar.policy_id,
    ar.required_role,
    ar.tier,
    ar.status,
    ar.reason,
    ar.decision_notes,
    ar.decided_by,
    ar.decided_at,
    ar.requested_at,
    ar.created_at,
    ar.updated_at,
    (EXTRACT(epoch FROM (COALESCE(ar.decided_at, now()) - ar.requested_at)) / (3600)::numeric) AS hours_to_decision,
    d.scope,
    d.deal_type,
    d.stage,
    d.approval_state,
    d.estimated_discount_pct,
    d.is_non_standard_term,
    d.is_exception,
    p.name AS policy_name
   FROM ((public.approval_requests ar
     JOIN public.renewal_expansion_deals d ON ((d.id = ar.deal_id)))
     LEFT JOIN public.approval_policies p ON ((p.id = ar.policy_id)));


--
-- Name: v_open_recommendations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_open_recommendations AS
 SELECT id,
    domain,
    kind,
    tier,
    severity,
    title,
    detail,
    drill_route,
    dedupe_key,
    payload,
    status,
    resolved_reason,
    resolved_by,
    resolved_at,
    first_detected_at,
    last_detected_at,
    created_at,
    updated_at,
        CASE severity
            WHEN 'critical'::text THEN 4
            WHEN 'warn'::text THEN 3
            WHEN 'notice'::text THEN 2
            ELSE 1
        END AS severity_rank
   FROM public.automation_recommendations
  WHERE (status = 'open'::text);


