   FROM public.v_open_recommendations;


--
-- Name: v_bi_capacity_assumptions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_capacity_assumptions WITH (security_invoker='true') AS
 SELECT scope,
    csm_accounts_per_head,
    support_tickets_per_agent_per_month,
    implementation_projects_per_specialist,
    wl_rollout_per_ops_head,
    arpu_assumption,
    tickets_per_account_per_month,
    new_projects_per_new_account,
    active,
    notes,
    updated_by,
    created_at,
    updated_at
   FROM public.capacity_assumptions;


--
-- Name: v_forecast_horizon; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_horizon WITH (security_invoker='true') AS
 WITH a AS (
         SELECT forecast_assumptions.horizon_months
           FROM public.forecast_assumptions
          WHERE (forecast_assumptions.assumption_key = 'default'::text)
        )
 SELECT (gs.gs)::date AS month_start,
    (((gs.gs + '1 mon'::interval) - '1 day'::interval))::date AS month_end,
    to_char(gs.gs, 'YYYY-MM'::text) AS period,
    (row_number() OVER (ORDER BY gs.gs))::integer AS month_index
   FROM a,
    LATERAL generate_series(date_trunc('month'::text, now()), (date_trunc('month'::text, now()) + (((a.horizon_months - 1) || ' months'::text))::interval), '1 mon'::interval) gs(gs);


--
-- Name: v_subscription_snapshot; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_subscription_snapshot WITH (security_invoker='true') AS
 WITH acq AS (
         SELECT DISTINCT ON (i.client_lead_id) i.client_lead_id AS lead_id,
                CASE
                    WHEN (i.partner_id IS NOT NULL) THEN 'wl'::text
                    ELSE 'direct'::text
                END AS acquisition_type,
            i.partner_id
           FROM public.internal_fulfillment_intakes i
          WHERE (i.client_lead_id IS NOT NULL)
          ORDER BY i.client_lead_id, i.created_at
        ), plan AS (
         SELECT DISTINCT ON (cp.lead_id) cp.lead_id,
            cp.plan_name AS custom_plan_name,
            cp.plan_type AS custom_plan_type,
            cp.minimum_monthly,
            cp.fixed_amount,
            cp.minute_rate,
            cp.is_active AS custom_plan_active
           FROM public.custom_plans cp
          WHERE (cp.is_active IS TRUE)
          ORDER BY cp.lead_id, cp.updated_at DESC NULLS LAST
        )
 SELECT l.id AS lead_id,
    l.name,
    l.company,
    COALESCE(a.acquisition_type, 'direct'::text) AS acquisition_type,
    a.partner_id,
    l.service_type,
    COALESCE(p.custom_plan_name, l.custom_plan_name, l.service_type) AS plan_name,
    l.plan_minutes,
    COALESCE(NULLIF(l.billing_period, ''::text), 'monthly'::text) AS billing_interval,
    l.stripe_customer_id,
    l.stripe_subscription_id,
    l.subscription_started_at,
    l.last_payment_status,
    l.pipeline_stage,
    l.status,
        CASE
            WHEN ((l.pipeline_stage = ANY (ARRAY['churned'::text, 'lost'::text])) OR (l.status = ANY (ARRAY['canceled'::text, 'churned'::text, 'cancelled'::text]))) THEN 'canceled'::text
            WHEN (l.last_payment_status = ANY (ARRAY['failed'::text, 'past_due'::text])) THEN 'past_due'::text
            WHEN ((l.stripe_subscription_id IS NOT NULL) OR (l.subscription_started_at IS NOT NULL)) THEN 'active'::text
            WHEN (l.pipeline_stage = 'onboarding'::text) THEN 'incomplete'::text
            ELSE 'unknown'::text
        END AS subscription_state,
        CASE
            WHEN (COALESCE(p.minimum_monthly, p.fixed_amount) IS NOT NULL) THEN COALESCE(p.minimum_monthly, p.fixed_amount)
            ELSE NULL::numeric
        END AS mrr_usd,
        CASE
            WHEN (p.minimum_monthly IS NOT NULL) THEN 'custom_plan_minimum_monthly'::text
            WHEN (p.fixed_amount IS NOT NULL) THEN 'custom_plan_fixed_amount'::text
            ELSE 'unknown'::text
        END AS mrr_basis,
    l.subscription_started_at AS effective_start_at,
        CASE
            WHEN (l.pipeline_stage = ANY (ARRAY['churned'::text, 'lost'::text])) THEN l.updated_at
            ELSE NULL::timestamp with time zone
        END AS effective_end_at,
    l.updated_at AS last_state_change_at
   FROM ((public.leads l
     LEFT JOIN acq a ON ((a.lead_id = l.id)))
     LEFT JOIN plan p ON ((p.lead_id = l.id)))
  WHERE ((l.stripe_subscription_id IS NOT NULL) OR (l.subscription_started_at IS NOT NULL) OR (l.pipeline_stage = ANY (ARRAY['active'::text, 'churned'::text, 'onboarding'::text, 'ready_for_billing'::text, 'won'::text])));


--
-- Name: v_forecast_existing_base; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_existing_base WITH (security_invoker='true') AS
 WITH base AS (
         SELECT COALESCE(sum(v_subscription_snapshot.mrr_usd) FILTER (WHERE (v_subscription_snapshot.subscription_state = 'active'::text)), (0)::numeric) AS starting_mrr
           FROM public.v_subscription_snapshot
        ), a AS (
         SELECT forecast_assumptions.baseline_monthly_churn_rate,
            forecast_assumptions.baseline_monthly_expansion_rate
           FROM public.forecast_assumptions
          WHERE (forecast_assumptions.assumption_key = 'default'::text)
        ), h AS (
         SELECT v_forecast_horizon.month_start,
            v_forecast_horizon.month_end,
            v_forecast_horizon.period,
            v_forecast_horizon.month_index
           FROM public.v_forecast_horizon
        )
 SELECT h.period,
    h.month_start,
    h.month_index,
    round((base.starting_mrr * power((((1)::numeric - a.baseline_monthly_churn_rate) + a.baseline_monthly_expansion_rate), ((h.month_index - 1))::numeric)), 2) AS projected_base_mrr,
    round(base.starting_mrr, 2) AS starting_mrr,
    a.baseline_monthly_churn_rate,
    a.baseline_monthly_expansion_rate
   FROM ((h
     CROSS JOIN base)
     CROSS JOIN a);


--
-- Name: v_forecast_expansion_deals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_expansion_deals WITH (security_invoker='true') AS
 WITH h AS (
         SELECT v_forecast_horizon.month_start,
            v_forecast_horizon.month_end,
            v_forecast_horizon.period,
            v_forecast_horizon.month_index
           FROM public.v_forecast_horizon
        ), deals AS (
         SELECT d_1.id,
            d_1.deal_type,
            d_1.stage,
            d_1.expected_close_date,
            COALESCE(p.probability, 0.2) AS prob,
            COALESCE((date_trunc('month'::text, (d_1.expected_close_date)::timestamp with time zone))::date, (date_trunc('month'::text, (d_1.stage_changed_at + '30 days'::interval)))::date) AS month_start
           FROM (public.renewal_expansion_deals d_1
             LEFT JOIN public.forecast_stage_probabilities p ON (((p.deal_type = d_1.deal_type) AND (p.stage = d_1.stage))))
          WHERE ((d_1.status = 'open'::public.deal_status) AND (d_1.deal_type = ANY (ARRAY['expansion'::public.deal_type, 'downsell'::public.deal_type, 'save'::public.deal_type])))
        )
 SELECT h.period,
    h.month_start,
    h.month_index,
    (count(d.id) FILTER (WHERE (d.deal_type = 'expansion'::public.deal_type)))::integer AS expansion_deals_open,
    COALESCE(round(sum(d.prob) FILTER (WHERE (d.deal_type = 'expansion'::public.deal_type)), 4), (0)::numeric) AS weighted_expansion_count,
    (count(d.id) FILTER (WHERE (d.deal_type = 'downsell'::public.deal_type)))::integer AS downsell_deals_open,
    COALESCE(round(sum(d.prob) FILTER (WHERE (d.deal_type = 'downsell'::public.deal_type)), 4), (0)::numeric) AS weighted_downsell_count,
    (count(d.id) FILTER (WHERE (d.deal_type = 'save'::public.deal_type)))::integer AS save_deals_open,
    COALESCE(round(sum(d.prob) FILTER (WHERE (d.deal_type = 'save'::public.deal_type)), 4), (0)::numeric) AS weighted_save_count
   FROM (h
     LEFT JOIN deals d ON ((d.month_start = h.month_start)))
  GROUP BY h.period, h.month_start, h.month_index
  ORDER BY h.month_index;


--
-- Name: v_forecast_renewals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_renewals WITH (security_invoker='true') AS
 WITH h AS (
         SELECT v_forecast_horizon.month_start,
            v_forecast_horizon.month_end,
            v_forecast_horizon.period,
            v_forecast_horizon.month_index
           FROM public.v_forecast_horizon
        ), rw AS (
         SELECT rw_1.id,
            rw_1.renewal_date,
            rw_1.stage AS workflow_stage,
            (date_trunc('month'::text, (rw_1.renewal_date)::timestamp with time zone))::date AS month_start
           FROM public.renewal_workflows rw_1
          WHERE ((rw_1.renewal_date >= date_trunc('month'::text, now())) AND (rw_1.renewal_date < (date_trunc('month'::text, now()) + '2 years'::interval)) AND (rw_1.stage <> ALL (ARRAY['renewed'::text, 'downgraded'::text, 'churned'::text, 'lapsed'::text])))
        ), linked AS (
         SELECT d.related_renewal_workflow_id AS rw_id,
            COALESCE(p.probability, 0.5) AS prob
           FROM (public.renewal_expansion_deals d
             LEFT JOIN public.forecast_stage_probabilities p ON (((p.deal_type = d.deal_type) AND (p.stage = d.stage))))
          WHERE ((d.related_renewal_workflow_id IS NOT NULL) AND (d.status = 'open'::public.deal_status))
        )
 SELECT h.period,
    h.month_start,
    h.month_index,
    (count(rw.id))::integer AS renewals_due,
    (count(rw.id) FILTER (WHERE (l.rw_id IS NOT NULL)))::integer AS renewals_with_open_deal,
    COALESCE(round(sum(COALESCE(l.prob, 0.85)), 4), (0)::numeric) AS weighted_expected_renewed_count,
    ((count(rw.id))::numeric - COALESCE(round(sum(COALESCE(l.prob, 0.85)), 4), (0)::numeric)) AS weighted_expected_lost_count
   FROM ((h
     LEFT JOIN rw ON ((rw.month_start = h.month_start)))
     LEFT JOIN linked l ON ((l.rw_id = rw.id)))
  GROUP BY h.period, h.month_start, h.month_index
  ORDER BY h.month_index;


--
-- Name: v_forecast_assembled; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_assembled WITH (security_invoker='true') AS
 WITH a AS (
         SELECT forecast_assumptions.new_business_mrr_direct,
            forecast_assumptions.new_business_mrr_wl,
            forecast_assumptions.baseline_monthly_churn_rate,
            forecast_assumptions.baseline_monthly_expansion_rate
           FROM public.forecast_assumptions
          WHERE (forecast_assumptions.assumption_key = 'default'::text)
        )
 SELECT b.period,
    b.month_start,
    b.month_index,
    b.starting_mrr,
    b.projected_base_mrr,
    round((b.projected_base_mrr * a.baseline_monthly_churn_rate), 2) AS baseline_churn_amount,
    round((b.projected_base_mrr * a.baseline_monthly_expansion_rate), 2) AS baseline_expansion_amount,
    round((a.new_business_mrr_direct + a.new_business_mrr_wl), 2) AS new_business_mrr,
    a.new_business_mrr_direct,
    a.new_business_mrr_wl,
    round(((((b.projected_base_mrr + a.new_business_mrr_direct) + a.new_business_mrr_wl) + (b.projected_base_mrr * a.baseline_monthly_expansion_rate)) - (b.projected_base_mrr * a.baseline_monthly_churn_rate)), 2) AS projected_ending_mrr,
    r.renewals_due,
    r.weighted_expected_renewed_count,
    r.weighted_expected_lost_count,
    e.expansion_deals_open,
    e.weighted_expansion_count,
    e.downsell_deals_open,
    e.weighted_downsell_count,
    e.save_deals_open,
    e.weighted_save_count
   FROM (((public.v_forecast_existing_base b
     CROSS JOIN a)
     LEFT JOIN public.v_forecast_renewals r ON ((r.month_index = b.month_index)))
     LEFT JOIN public.v_forecast_expansion_deals e ON ((e.month_index = b.month_index)))
  ORDER BY b.month_index;


--
-- Name: v_capacity_demand; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_capacity_demand WITH (security_invoker='true') AS
 WITH a AS (
         SELECT capacity_assumptions.scope,
            capacity_assumptions.csm_accounts_per_head,
            capacity_assumptions.support_tickets_per_agent_per_month,
            capacity_assumptions.implementation_projects_per_specialist,
            capacity_assumptions.wl_rollout_per_ops_head,
            capacity_assumptions.arpu_assumption,
            capacity_assumptions.tickets_per_account_per_month,
            capacity_assumptions.new_projects_per_new_account,
            capacity_assumptions.active,
            capacity_assumptions.notes,
            capacity_assumptions.updated_by,
            capacity_assumptions.created_at,
            capacity_assumptions.updated_at
           FROM public.capacity_assumptions
          WHERE (capacity_assumptions.active AND (capacity_assumptions.scope = 'both'::text))
         LIMIT 1
        )
 SELECT f.month_start AS period,
    f.period AS period_label,
    f.month_index,
    'both'::text AS scope,
    f.projected_ending_mrr,
    f.new_business_mrr_direct,
    f.new_business_mrr_wl,
    round((f.projected_ending_mrr / NULLIF(a.arpu_assumption, (0)::numeric)), 2) AS forecasted_active_accounts,
    round(((COALESCE(f.new_business_mrr_direct, (0)::numeric) + COALESCE(f.new_business_mrr_wl, (0)::numeric)) / NULLIF(a.arpu_assumption, (0)::numeric)), 2) AS forecasted_new_accounts,
    round(((f.projected_ending_mrr / NULLIF(a.arpu_assumption, (0)::numeric)) / (a.csm_accounts_per_head)::numeric), 2) AS needed_csm_heads,
    round((((f.projected_ending_mrr / NULLIF(a.arpu_assumption, (0)::numeric)) * a.tickets_per_account_per_month) / (NULLIF(a.support_tickets_per_agent_per_month, 0))::numeric), 2) AS needed_support_heads,
    round(((((COALESCE(f.new_business_mrr_direct, (0)::numeric) + COALESCE(f.new_business_mrr_wl, (0)::numeric)) / NULLIF(a.arpu_assumption, (0)::numeric)) * a.new_projects_per_new_account) / (NULLIF(a.implementation_projects_per_specialist, 0))::numeric), 2) AS needed_implementation_heads,
    round(((COALESCE(f.new_business_mrr_wl, (0)::numeric) / NULLIF(a.arpu_assumption, (0)::numeric)) / (NULLIF(a.wl_rollout_per_ops_head, 0))::numeric), 2) AS needed_wl_ops_heads,
    a.arpu_assumption,
    a.csm_accounts_per_head,
    a.tickets_per_account_per_month,
    a.support_tickets_per_agent_per_month,
    a.new_projects_per_new_account,
    a.implementation_projects_per_specialist,
    a.wl_rollout_per_ops_head
   FROM (public.v_forecast_assembled f
     CROSS JOIN a)
  ORDER BY f.month_index;


--
-- Name: v_bi_capacity_demand; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_capacity_demand WITH (security_invoker='true') AS
 SELECT period,
    period_label,
    month_index,
    scope,
    projected_ending_mrr,
    new_business_mrr_direct,
    new_business_mrr_wl,
    forecasted_active_accounts,
    forecasted_new_accounts,
    needed_csm_heads,
    needed_support_heads,
    needed_implementation_heads,
    needed_wl_ops_heads,
    arpu_assumption,
    csm_accounts_per_head,
    tickets_per_account_per_month,
    support_tickets_per_agent_per_month,
    new_projects_per_new_account,
    implementation_projects_per_specialist,
    wl_rollout_per_ops_head
   FROM public.v_capacity_demand;


--
-- Name: v_capacity_supply_current; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_capacity_supply_current WITH (security_invoker='true') AS
 SELECT DISTINCT ON (scope, function) scope,
    function,
    current_headcount,
    planned_headcount,
    effective_date,
    notes
   FROM public.capacity_supply
  WHERE (effective_date <= CURRENT_DATE)
  ORDER BY scope, function, effective_date DESC;


--
-- Name: v_capacity_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_capacity_gaps WITH (security_invoker='true') AS
 WITH demand AS (
         SELECT v_capacity_demand.period,
            v_capacity_demand.month_index,
            v_capacity_demand.scope,
            v_capacity_demand.needed_csm_heads,
            v_capacity_demand.needed_support_heads,
            v_capacity_demand.needed_implementation_heads,
            v_capacity_demand.needed_wl_ops_heads
           FROM public.v_capacity_demand
        ), supply AS (
         SELECT v_capacity_supply_current.scope,
            v_capacity_supply_current.function,
            v_capacity_supply_current.current_headcount,
            v_capacity_supply_current.planned_headcount
           FROM public.v_capacity_supply_current
        ), unpivoted AS (
         SELECT demand.period,
            demand.month_index,
            demand.scope,
            'csm'::text AS function,
            demand.needed_csm_heads AS demand
           FROM demand
        UNION ALL
         SELECT demand.period,
            demand.month_index,
            demand.scope,
            'support'::text,
            demand.needed_support_heads
           FROM demand
        UNION ALL
         SELECT demand.period,
            demand.month_index,
            demand.scope,
            'implementation'::text,
            demand.needed_implementation_heads
           FROM demand
        UNION ALL
         SELECT demand.period,
            demand.month_index,
            demand.scope,
            'wl_ops'::text,
            demand.needed_wl_ops_heads
           FROM demand
        )
 SELECT u.period,
    u.month_index,
    u.scope,
    u.function,
    u.demand,
    COALESCE(s.current_headcount, (0)::numeric) AS current_supply,
    s.planned_headcount,
    round((COALESCE(s.current_headcount, (0)::numeric) - u.demand), 2) AS gap_now,
    round((COALESCE(s.planned_headcount, s.current_headcount, (0)::numeric) - u.demand), 2) AS gap_planned,
        CASE
            WHEN ((u.demand IS NULL) OR (u.demand = (0)::numeric)) THEN NULL::numeric
            ELSE round(((COALESCE(s.current_headcount, (0)::numeric) - u.demand) / u.demand), 4)
        END AS over_under_pct
   FROM (unpivoted u
     LEFT JOIN supply s ON (((s.function = u.function) AND ((s.scope = u.scope) OR (s.scope = 'both'::text) OR (u.scope = 'both'::text)))))
  ORDER BY u.month_index, u.function;


--
-- Name: v_bi_capacity_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_capacity_gaps WITH (security_invoker='true') AS
 SELECT period,
    month_index,
    scope,
    function,
    demand,
    current_supply,
    planned_headcount,
    gap_now,
    gap_planned,
    over_under_pct
   FROM public.v_capacity_gaps;


--
-- Name: v_bi_capacity_supply; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_capacity_supply WITH (security_invoker='true') AS
 SELECT id,
    scope,
    function,
    current_headcount,
    planned_headcount,
    effective_date,
    notes,
    updated_by,
    created_at,
    updated_at
   FROM public.capacity_supply;


--
-- Name: v_commercial_direct_vs_wl; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_commercial_direct_vs_wl WITH (security_invoker='true') AS
 SELECT source AS acquisition_type,
    (count(*))::integer AS intakes,
    (count(*) FILTER (WHERE (activated_at IS NOT NULL)))::integer AS activations,
    round((((count(*) FILTER (WHERE (activated_at IS NOT NULL)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS activation_rate_pct,
    round(avg((EXTRACT(epoch FROM (activated_at - submitted_at)) / 86400.0)), 1) AS avg_days_to_activate,
    (count(DISTINCT partner_id) FILTER (WHERE (source = 'wl'::text)))::integer AS distinct_wl_partners
   FROM public.internal_fulfillment_intakes i
  GROUP BY source;


--
-- Name: VIEW v_commercial_direct_vs_wl; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_commercial_direct_vs_wl IS 'Phase 14: direct vs WL commercial throughput. Honest measure of intake-to-activation conversion and speed.';


--
-- Name: v_bi_commercial_direct_vs_wl; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_commercial_direct_vs_wl WITH (security_invoker='true') AS
 SELECT acquisition_type,
    intakes,
    activations,
    activation_rate_pct,
    avg_days_to_activate,
    distinct_wl_partners
   FROM public.v_commercial_direct_vs_wl;


--
-- Name: VIEW v_bi_commercial_direct_vs_wl; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_bi_commercial_direct_vs_wl IS 'Phase 14 BI mirror — stable schema for export.';


--
-- Name: v_commercial_lifecycle_signals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_commercial_lifecycle_signals WITH (security_invoker='true') AS
 WITH ranked AS (
         SELECT bs.client_id,
            bs.period_end,
            bs.total_minutes,
            bs.included_minutes,
            bs.overage_minutes,
            bs.plan_name,
            row_number() OVER (PARTITION BY bs.client_id ORDER BY bs.period_end DESC) AS rn,
            count(*) OVER (PARTITION BY bs.client_id) AS period_count
           FROM public.billing_summaries bs
        ), latest AS (
         SELECT ranked.client_id,
            ranked.period_end,
            ranked.total_minutes,
            ranked.included_minutes,
            ranked.overage_minutes,
            ranked.plan_name,
            ranked.rn,
            ranked.period_count
           FROM ranked
          WHERE (ranked.rn = 1)
        ), prior AS (
         SELECT ranked.client_id,
            ranked.period_end,
            ranked.total_minutes,
            ranked.included_minutes,
            ranked.overage_minutes,
            ranked.plan_name,
            ranked.rn,
            ranked.period_count
           FROM ranked
          WHERE (ranked.rn = 2)
        )
 SELECT l.client_id,
    COALESCE(NULLIF(TRIM(BOTH FROM l.plan_name), ''::text), 'unknown'::text) AS plan_name,
    l.period_end AS latest_period_end,
    l.total_minutes AS latest_minutes,
    p.total_minutes AS prior_minutes,
        CASE
            WHEN (l.period_count < 2) THEN 'insufficient_history'::text
            WHEN ((l.included_minutes > 0) AND (p.included_minutes > 0) AND ((((l.overage_minutes)::numeric / (l.included_minutes)::numeric) - ((p.overage_minutes)::numeric / (NULLIF(p.included_minutes, 0))::numeric)) >= 0.25)) THEN 'expansion'::text
            WHEN ((p.total_minutes > 0) AND ((l.total_minutes)::numeric < ((p.total_minutes)::numeric * 0.75))) THEN 'downgrade_risk'::text
            WHEN (l.period_end < (now() - '60 days'::interval)) THEN 'stalled'::text
            ELSE 'steady'::text
        END AS signal,
    l.period_count AS observed_periods
   FROM (latest l
     LEFT JOIN prior p USING (client_id));


--
-- Name: VIEW v_commercial_lifecycle_signals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_commercial_lifecycle_signals IS 'Phase 14: bounded heuristic signals per client (expansion/downgrade_risk/stalled/steady/insufficient_history). Proxies — not churn predictions.';


--
-- Name: v_bi_commercial_lifecycle_signals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_commercial_lifecycle_signals WITH (security_invoker='true') AS
 SELECT client_id,
    plan_name,
    latest_period_end,
    latest_minutes,
    prior_minutes,
    signal,
    observed_periods
   FROM public.v_commercial_lifecycle_signals;


--
-- Name: VIEW v_bi_commercial_lifecycle_signals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_bi_commercial_lifecycle_signals IS 'Phase 14 BI mirror — stable schema for export.';


--
-- Name: v_commercial_plan_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_commercial_plan_performance WITH (security_invoker='true') AS
 SELECT COALESCE(NULLIF(TRIM(BOTH FROM plan_name), ''::text), 'unknown'::text) AS plan_name,
    (count(*))::integer AS billing_periods,
    (count(DISTINCT client_id))::integer AS distinct_clients,
    sum(total_minutes) AS total_minutes,
    sum(included_minutes) AS included_minutes,
    sum(overage_minutes) AS overage_minutes,
    round(sum(overage_amount), 2) AS overage_revenue_proxy,
    round((((count(*) FILTER (WHERE (overage_minutes > 0)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS pct_periods_with_overage,
    round(avg(
        CASE
            WHEN (included_minutes > 0) THEN (((overage_minutes)::numeric / (included_minutes)::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END), 1) AS avg_overage_pct_of_included,
    max(period_end) AS latest_period_end
   FROM public.billing_summaries bs
  GROUP BY COALESCE(NULLIF(TRIM(BOTH FROM plan_name), ''::text), 'unknown'::text);


--
-- Name: VIEW v_commercial_plan_performance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_commercial_plan_performance IS 'Phase 14: per-package performance from billing_summaries. overage_revenue_proxy is overage_amount only (not full MRR). Unknown plan_name preserved.';


--
-- Name: v_bi_commercial_plan_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_commercial_plan_performance WITH (security_invoker='true') AS
 SELECT plan_name,
    billing_periods,
    distinct_clients,
    total_minutes,
    included_minutes,
    overage_minutes,
    overage_revenue_proxy,
    pct_periods_with_overage,
    avg_overage_pct_of_included,
    latest_period_end
   FROM public.v_commercial_plan_performance;


--
-- Name: VIEW v_bi_commercial_plan_performance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_bi_commercial_plan_performance IS 'Phase 14 BI mirror — stable schema for export.';


--
-- Name: wl_invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wl_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_id uuid NOT NULL,
    billing_period_start date NOT NULL,
    billing_period_end date NOT NULL,
    invoice_number text NOT NULL,
    amount numeric NOT NULL,
    status text DEFAULT 'paid'::text NOT NULL,
    stripe_invoice_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: v_commercial_revenue_mix; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_commercial_revenue_mix WITH (security_invoker='true') AS
 WITH direct_proxy AS (
         SELECT 'direct'::text AS stream,
            'overage_revenue_proxy'::text AS metric_label,
            round(COALESCE(sum(billing_summaries.overage_amount), (0)::numeric), 2) AS amount,
            (count(*))::integer AS records,
            max(billing_summaries.period_end) AS latest_at
           FROM public.billing_summaries
          WHERE (billing_summaries.period_end >= (now() - '365 days'::interval))
        ), wl_paid AS (
         SELECT 'wl'::text AS stream,
            'wl_invoice_paid'::text AS metric_label,
            round(COALESCE(sum(wl_invoices.amount), (0)::numeric), 2) AS amount,
            (count(*))::integer AS records,
            max((wl_invoices.billing_period_end)::timestamp with time zone) AS latest_at
           FROM public.wl_invoices
          WHERE ((wl_invoices.status = 'paid'::text) AND (wl_invoices.billing_period_end >= (CURRENT_DATE - 365)))
        )
 SELECT direct_proxy.stream,
    direct_proxy.metric_label,
    direct_proxy.amount,
    direct_proxy.records,
    direct_proxy.latest_at
   FROM direct_proxy
UNION ALL
 SELECT wl_paid.stream,
    wl_paid.metric_label,
    wl_paid.amount,
    wl_paid.records,
    wl_paid.latest_at
   FROM wl_paid;


--
-- Name: VIEW v_commercial_revenue_mix; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_commercial_revenue_mix IS 'Phase 14 PROXY: direct stream is overage-only (no canonical contract MRR); WL stream is paid invoices. Not a financial statement.';


--
-- Name: v_bi_commercial_revenue_mix; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_commercial_revenue_mix WITH (security_invoker='true') AS
 SELECT stream,
    metric_label,
    amount,
    records,
    latest_at
   FROM public.v_commercial_revenue_mix;


--
-- Name: VIEW v_bi_commercial_revenue_mix; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_bi_commercial_revenue_mix IS 'Phase 14 BI mirror — stable schema for export. Proxy fields labeled.';


