--
-- Name: v_delivery_pipeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_delivery_pipeline WITH (security_invoker='true') AS
 SELECT status,
    (count(*))::integer AS intake_count,
    (count(*) FILTER (WHERE (priority = 'urgent'::text)))::integer AS urgent_count,
    (count(*) FILTER (WHERE (assigned_to IS NULL)))::integer AS unassigned_count,
    (count(*) FILTER (WHERE (source = 'wl'::text)))::integer AS wl_count,
    (count(*) FILTER (WHERE (source = 'direct'::text)))::integer AS direct_count,
    min(submitted_at) AS oldest_submitted_at
   FROM public.internal_fulfillment_intakes
  WHERE (status <> 'closed'::text)
  GROUP BY status;


--
-- Name: v_bi_delivery_pipeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_delivery_pipeline WITH (security_invoker='true') AS
 SELECT status,
    intake_count,
    urgent_count,
    unassigned_count,
    wl_count,
    direct_count,
    oldest_submitted_at,
    now() AS as_of
   FROM public.v_delivery_pipeline;


--
-- Name: v_client_delivery_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_client_delivery_status WITH (security_invoker='true') AS
 SELECT l.id AS lead_id,
    l.name,
    l.company,
        CASE
            WHEN (h.status IS NULL) THEN 'not_started'::text
            WHEN (h.status = 'collecting_info'::text) THEN 'collecting_info'::text
            WHEN (h.status = ANY (ARRAY['submitted'::text, 'in_review'::text])) THEN 'in_review'::text
            WHEN (h.status = 'activated'::text) THEN 'live'::text
            ELSE h.status
        END AS service_state,
    h.status AS onboarding_status,
    i.status AS fulfillment_status,
    i.intake_number,
    i.activated_at,
    ( SELECT (count(*))::integer AS count
           FROM public.campaigns c
          WHERE ((c.client_lead_id = l.id) AND (c.status = 'live'::text))) AS live_campaigns_count,
    ( SELECT (count(*))::integer AS count
           FROM public.campaigns c
          WHERE (c.client_lead_id = l.id)) AS total_campaigns_count,
    ( SELECT (count(*))::integer AS count
           FROM public.support_tickets st
          WHERE ((st.lead_id = l.id) AND (st.status <> ALL (ARRAY['resolved'::text, 'closed'::text])))) AS open_tickets_count,
    ( SELECT max(de.occurred_at) AS max
           FROM public.dashboard_events de
          WHERE ((de.target = (i.id)::text) AND (de.event_name ~~ 'delivery.%'::text))) AS last_delivery_event_at
   FROM ((public.leads l
     LEFT JOIN public.client_onboarding_handoffs h ON ((h.client_lead_id = l.id)))
     LEFT JOIN LATERAL ( SELECT internal_fulfillment_intakes.id,
            internal_fulfillment_intakes.partner_id,
            internal_fulfillment_intakes.source_handoff_id,
            internal_fulfillment_intakes.proposal_id,
            internal_fulfillment_intakes.lead_id,
            internal_fulfillment_intakes.intake_number,
            internal_fulfillment_intakes.status,
            internal_fulfillment_intakes.priority,
            internal_fulfillment_intakes.submitted_by,
            internal_fulfillment_intakes.submitted_at,
            internal_fulfillment_intakes.received_at,
            internal_fulfillment_intakes.approved_at,
            internal_fulfillment_intakes.activated_at,
            internal_fulfillment_intakes.closed_at,
            internal_fulfillment_intakes.assigned_to,
            internal_fulfillment_intakes.snapshot_json,
            internal_fulfillment_intakes.snapshot_version,
            internal_fulfillment_intakes.created_at,
            internal_fulfillment_intakes.updated_at,
            internal_fulfillment_intakes.source,
            internal_fulfillment_intakes.client_lead_id
           FROM public.internal_fulfillment_intakes
          WHERE (internal_fulfillment_intakes.client_lead_id = l.id)
          ORDER BY internal_fulfillment_intakes.submitted_at DESC NULLS LAST
         LIMIT 1) i ON (true))
  WHERE ((l.user_id = auth.uid()) OR (h.client_user_id = auth.uid()));


--
-- Name: v_success_account_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_success_account_status WITH (security_invoker='true') AS
 WITH base AS (
         SELECT d.lead_id,
            d.name,
            d.company,
            d.service_state,
            d.activated_at,
            d.open_tickets_count,
            d.live_campaigns_count,
            d.total_campaigns_count,
            d.last_delivery_event_at,
            (GREATEST((0)::numeric, EXTRACT(day FROM (now() - d.activated_at))))::integer AS days_live,
            (GREATEST((0)::numeric, EXTRACT(day FROM (now() - COALESCE(d.last_delivery_event_at, d.activated_at)))))::integer AS days_since_activity
           FROM public.v_client_delivery_status d
          WHERE (d.service_state = 'live'::text)
        ), recept AS (
         SELECT a_1.client_lead_id AS lead_id,
            a_1.flow_count,
            a_1.live_count,
            a_1.pending_count,
            a_1.unconfigured_count,
            a_1.last_validated_at
           FROM public.v_account_receptionist_status a_1
          WHERE (a_1.client_lead_id IS NOT NULL)
        ), lifecycle AS (
         SELECT s.client_id AS lead_id,
            s.signal,
            s.plan_name,
            s.latest_period_end
           FROM public.v_commercial_lifecycle_signals s
        ), acq AS (
         SELECT DISTINCT ON (i.client_lead_id) i.client_lead_id AS lead_id,
                CASE
                    WHEN (i.partner_id IS NOT NULL) THEN 'wl'::text
                    ELSE 'direct'::text
                END AS acquisition_type,
            i.partner_id
           FROM public.internal_fulfillment_intakes i
          WHERE (i.client_lead_id IS NOT NULL)
          ORDER BY i.client_lead_id, i.activated_at DESC NULLS LAST, i.created_at DESC
        )
 SELECT b.lead_id,
    b.name,
    b.company,
    COALESCE(a.acquisition_type, 'direct'::text) AS acquisition_type,
    a.partner_id,
    b.activated_at,
    b.days_live,
    b.days_since_activity,
    b.open_tickets_count,
    b.live_campaigns_count,
    b.total_campaigns_count,
    (COALESCE(r.flow_count, (0)::bigint))::integer AS receptionist_flow_count,
    (COALESCE(r.live_count, (0)::bigint))::integer AS receptionist_live_count,
    (COALESCE(r.pending_count, (0)::bigint))::integer AS receptionist_pending_count,
        CASE
            WHEN (COALESCE(r.flow_count, (0)::bigint) = 0) THEN 'missing'::text
            WHEN (COALESCE(r.live_count, (0)::bigint) = 0) THEN 'missing'::text
            WHEN (r.live_count = r.flow_count) THEN 'healthy'::text
            ELSE 'partial'::text
        END AS receptionist_health,
    COALESCE(l.signal, 'insufficient_history'::text) AS lifecycle_signal,
    l.plan_name,
    l.latest_period_end,
        CASE
            WHEN ((COALESCE(r.live_count, (0)::bigint) = 0) OR (l.signal = 'downgrade_risk'::text) OR (b.open_tickets_count >= 3) OR ((l.signal = 'stalled'::text) AND (b.days_since_activity >= 30))) THEN 'intervention'::text
            WHEN ((l.signal = 'stalled'::text) OR ((b.days_since_activity >= 14) AND (b.days_since_activity <= 29)) OR ((COALESCE(r.flow_count, (0)::bigint) > 0) AND (r.live_count < r.flow_count)) OR ((b.open_tickets_count >= 1) AND (b.open_tickets_count <= 2))) THEN 'watch'::text
            ELSE 'healthy'::text
        END AS health_band,
    array_remove(ARRAY[
        CASE
            WHEN (COALESCE(r.live_count, (0)::bigint) = 0) THEN 'no_live_receptionist'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((COALESCE(r.flow_count, (0)::bigint) > 0) AND (r.live_count < r.flow_count)) THEN 'partial_receptionist'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (l.signal = 'downgrade_risk'::text) THEN 'downgrade_risk_signal'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (l.signal = 'stalled'::text) THEN 'stalled_usage'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (b.open_tickets_count >= 3) THEN 'high_open_tickets'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((b.open_tickets_count >= 1) AND (b.open_tickets_count <= 2)) THEN 'open_tickets'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (b.days_since_activity >= 30) THEN 'dormant_30d'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((b.days_since_activity >= 14) AND (b.days_since_activity <= 29)) THEN 'low_activity_14d'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (l.signal = 'expansion'::text) THEN 'expansion_signal'::text
            ELSE NULL::text
        END], NULL::text) AS reasons
   FROM (((base b
     LEFT JOIN recept r ON ((r.lead_id = b.lead_id)))
     LEFT JOIN lifecycle l ON ((l.lead_id = b.lead_id)))
     LEFT JOIN acq a ON ((a.lead_id = b.lead_id)));


--
-- Name: VIEW v_success_account_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_success_account_status IS 'Phase 16. Per live-account success snapshot. Rule-based health_band + explicit reasons. SECURITY INVOKER; admin/billing RLS from underlying sources.';


--
-- Name: v_direct_success_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_direct_success_summary WITH (security_invoker='true') AS
 WITH base AS (
         SELECT s.lead_id,
            s.name,
            s.company,
            s.plan_name,
            s.activated_at,
            s.days_live,
            s.days_since_activity,
            s.open_tickets_count,
            s.live_campaigns_count,
            s.total_campaigns_count,
            s.receptionist_health,
            s.lifecycle_signal,
            s.health_band,
            s.reasons,
            sub.subscription_state,
            sub.last_payment_status,
            sub.mrr_usd,
            sub.mrr_basis
           FROM (public.v_success_account_status s
             LEFT JOIN public.v_subscription_snapshot sub ON ((sub.lead_id = s.lead_id)))
          WHERE (s.acquisition_type = 'direct'::text)
        ), flagged AS (
         SELECT b.lead_id,
            b.name,
            b.company,
            b.plan_name,
            b.activated_at,
            b.days_live,
            b.days_since_activity,
            b.open_tickets_count,
            b.live_campaigns_count,
            b.total_campaigns_count,
            b.receptionist_health,
            b.lifecycle_signal,
            b.health_band,
            b.reasons,
            b.subscription_state,
            b.last_payment_status,
            b.mrr_usd,
            b.mrr_basis,
            (b.subscription_state = 'past_due'::text) AS flag_payment_risk,
            (b.subscription_state = 'canceled'::text) AS flag_canceled,
            (b.health_band = 'intervention'::text) AS flag_intervention,
            (b.lifecycle_signal = 'downgrade_risk'::text) AS flag_downgrade_risk,
            (b.lifecycle_signal = 'expansion'::text) AS flag_expansion_signal,
            ((b.receptionist_health = 'missing'::text) AND (b.days_live > 7)) AS flag_no_receptionist,
            (b.open_tickets_count >= 3) AS flag_support_friction,
            ((b.days_since_activity >= 30) AND (b.days_live > 14)) AS flag_inactive,
            ((b.health_band = 'healthy'::text) AND (b.lifecycle_signal = 'expansion'::text) AND (COALESCE(b.subscription_state, 'unknown'::text) = 'active'::text) AND (b.days_live >= 30) AND (b.open_tickets_count = 0)) AS flag_expansion_ready,
            ((b.activated_at IS NOT NULL) AND (b.days_live <= 30) AND (b.health_band <> 'intervention'::text)) AS flag_new_account
           FROM base b
        )
 SELECT lead_id,
    name,
    company,
    plan_name,
    activated_at,
    days_live,
    days_since_activity,
    open_tickets_count,
    live_campaigns_count,
    total_campaigns_count,
    receptionist_health,
    lifecycle_signal,
    health_band,
    reasons,
    subscription_state,
    last_payment_status,
    mrr_usd,
    mrr_basis,
    flag_payment_risk,
    flag_canceled,
    flag_intervention,
    flag_downgrade_risk,
    flag_expansion_signal,
    flag_no_receptionist,
    flag_support_friction,
    flag_inactive,
    flag_expansion_ready,
    flag_new_account,
        CASE
            WHEN flag_canceled THEN 'at_risk'::text
            WHEN flag_payment_risk THEN 'at_risk'::text
            WHEN flag_intervention THEN 'at_risk'::text
            WHEN (flag_inactive AND (health_band = 'watch'::text)) THEN 'at_risk'::text
            WHEN (flag_downgrade_risk OR flag_no_receptionist OR flag_support_friction) THEN 'stabilize'::text
            WHEN flag_expansion_ready THEN 'expansion_ready'::text
            ELSE 'nurture'::text
        END AS success_state
   FROM flagged f;


--
-- Name: VIEW v_direct_success_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_direct_success_summary IS 'Phase 30: per direct-account success state with explainable flags. Sources v_success_account_status + v_subscription_snapshot. acquisition_type=direct only.';


--
-- Name: v_direct_success_opportunities; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_direct_success_opportunities WITH (security_invoker='true') AS
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'save'::text AS opportunity_type,
    1 AS priority,
    'Subscription past due'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE s.flag_payment_risk
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'reactivate'::text AS opportunity_type,
    1 AS priority,
    'Subscription canceled'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE s.flag_canceled
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'save'::text AS opportunity_type,
    1 AS priority,
    'Health band: intervention'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE s.flag_intervention
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'save'::text AS opportunity_type,
    2 AS priority,
    'Lifecycle signal: downgrade risk'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE (s.flag_downgrade_risk AND (NOT s.flag_intervention))
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'onboard'::text AS opportunity_type,
    2 AS priority,
    'No live receptionist after first week'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE (s.flag_no_receptionist AND (NOT s.flag_intervention))
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'save'::text AS opportunity_type,
    3 AS priority,
    '3+ open support tickets'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE (s.flag_support_friction AND (NOT s.flag_intervention))
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'reactivate'::text AS opportunity_type,
    3 AS priority,
    '30+ days without activity'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE (s.flag_inactive AND (NOT s.flag_canceled))
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'upsell'::text AS opportunity_type,
    1 AS priority,
    'Healthy account with expansion signals'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE s.flag_expansion_ready
UNION ALL
 SELECT s.lead_id,
    s.name,
    s.company,
    s.success_state,
    'educate'::text AS opportunity_type,
    3 AS priority,
    'New account in first 30 days'::text AS reason
   FROM public.v_direct_success_summary s
  WHERE s.flag_new_account;


