-- Name: v_bi_direct_success_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_direct_success_summary WITH (security_invoker='true') AS
 SELECT lead_id,
    name,
    company,
    plan_name,
    activated_at,
    days_live,
    days_since_activity,
    open_tickets_count,
    live_campaigns_count,
