    flag_new_account,
    success_state
   FROM public.v_direct_success_summary;


--
-- Name: v_subscription_churn_events; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_subscription_churn_events WITH (security_invoker='true') AS
 SELECT lead_id,
    name,
    company,
    acquisition_type,
    partner_id,
    plan_name,
    mrr_usd AS lost_mrr_usd,
    mrr_basis,
    effective_start_at,
    effective_end_at AS canceled_at,
    (GREATEST((0)::numeric, EXTRACT(day FROM (COALESCE(effective_end_at, now()) - COALESCE(effective_start_at, last_state_change_at)))))::integer AS lifetime_days
   FROM public.v_subscription_snapshot s
  WHERE (subscription_state = 'canceled'::text);


