--
-- Name: v_subscription_wl_recurring; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_subscription_wl_recurring WITH (security_invoker='true') AS
 WITH recent AS (
         SELECT i.partner_id,
            i.amount,
            i.billing_period_start
           FROM public.wl_invoices i
          WHERE ((i.status = 'paid'::text) AND (i.billing_period_start >= (now() - '120 days'::interval)))
        )
 SELECT p.id AS partner_id,
    p.company_name AS business_name,
    (count(r.*))::integer AS paid_invoices_90d,
    COALESCE(avg(r.amount), (0)::numeric) AS avg_monthly_recurring_usd,
    COALESCE(sum(r.amount), (0)::numeric) AS sum_recurring_90d_usd,
    max(r.billing_period_start) AS latest_paid_period
   FROM (public.white_label_partners p
     LEFT JOIN recent r ON ((r.partner_id = p.id)))
  GROUP BY p.id, p.company_name;


--
-- Name: v_exec_direct_vs_wl_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_exec_direct_vs_wl_summary WITH (security_invoker='true') AS
 WITH active AS (
         SELECT v_subscription_snapshot.acquisition_type,
            (count(*) FILTER (WHERE (v_subscription_snapshot.subscription_state = 'active'::text)))::integer AS active_subs,
            (count(*) FILTER (WHERE (v_subscription_snapshot.subscription_state = 'canceled'::text)))::integer AS canceled_subs,
            COALESCE(sum(v_subscription_snapshot.mrr_usd) FILTER (WHERE (v_subscription_snapshot.subscription_state = 'active'::text)), (0)::numeric) AS known_mrr_usd
           FROM public.v_subscription_snapshot
          GROUP BY v_subscription_snapshot.acquisition_type
        ), churn30 AS (
         SELECT v_subscription_churn_events.acquisition_type,
            (count(*))::integer AS churned_30d,
            COALESCE(sum(v_subscription_churn_events.lost_mrr_usd), (0)::numeric) AS churned_mrr_30d
           FROM public.v_subscription_churn_events
          WHERE (v_subscription_churn_events.canceled_at >= (now() - '30 days'::interval))
          GROUP BY v_subscription_churn_events.acquisition_type
        ), new30 AS (
         SELECT v_subscription_snapshot.acquisition_type,
            (count(*))::integer AS new_30d
           FROM public.v_subscription_snapshot
          WHERE (v_subscription_snapshot.subscription_started_at >= (now() - '30 days'::interval))
          GROUP BY v_subscription_snapshot.acquisition_type
        ), wl_proxy AS (
         SELECT 'wl'::text AS acquisition_type,
            COALESCE(sum(v_subscription_wl_recurring.avg_monthly_recurring_usd), (0)::numeric) AS wl_recurring_proxy_usd
           FROM public.v_subscription_wl_recurring
        )
 SELECT a.acquisition_type AS stream,
    a.active_subs,
    a.canceled_subs,
    a.known_mrr_usd,
        CASE
            WHEN (a.acquisition_type = 'wl'::text) THEN ( SELECT wl_proxy.wl_recurring_proxy_usd
               FROM wl_proxy)
            ELSE NULL::numeric
        END AS wl_recurring_proxy_usd,
    COALESCE(n.new_30d, 0) AS new_subs_30d,
    COALESCE(c.churned_30d, 0) AS churned_subs_30d,
    COALESCE(c.churned_mrr_30d, (0)::numeric) AS churned_mrr_30d,
        CASE
            WHEN (a.acquisition_type = 'wl'::text) THEN 'Direct=custom_plans MRR; WL=90d paid-invoice avg proxy'::text
            ELSE 'Direct=custom_plans MRR (minimum_monthly|fixed_amount)'::text
        END AS basis
   FROM ((active a
     LEFT JOIN new30 n ON ((n.acquisition_type = a.acquisition_type)))
     LEFT JOIN churn30 c ON ((c.acquisition_type = a.acquisition_type)));


--
-- Name: v_bi_exec_direct_vs_wl_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_exec_direct_vs_wl_summary WITH (security_invoker='true') AS
 SELECT stream,
    active_subs,
    canceled_subs,
    known_mrr_usd,
    wl_recurring_proxy_usd,
    new_subs_30d,
    churned_subs_30d,
    churned_mrr_30d,
    basis
   FROM public.v_exec_direct_vs_wl_summary;


--
-- Name: v_exec_mrr_spine; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_exec_mrr_spine WITH (security_invoker='true') AS
 WITH months AS (
         SELECT (generate_series(date_trunc('month'::text, (now() - '1 year 11 mons'::interval)), date_trunc('month'::text, now()), '1 mon'::interval))::date AS month_start
        ), spine AS (
         SELECT m.month_start,
            ((m.month_start + '1 mon'::interval))::date AS next_month,
            COALESCE(sum(s_1.mrr_usd) FILTER (WHERE ((s_1.mrr_usd IS NOT NULL) AND (s_1.effective_start_at IS NOT NULL) AND (s_1.effective_start_at < (m.month_start + '1 mon'::interval)) AND ((s_1.effective_end_at IS NULL) OR (s_1.effective_end_at >= (m.month_start + '1 mon'::interval))))), (0)::numeric) AS ending_mrr_usd,
            (count(*) FILTER (WHERE ((s_1.effective_start_at IS NOT NULL) AND (s_1.effective_start_at < (m.month_start + '1 mon'::interval)) AND ((s_1.effective_end_at IS NULL) OR (s_1.effective_end_at >= (m.month_start + '1 mon'::interval))))))::integer AS ending_active_subs
           FROM (months m
             LEFT JOIN public.v_subscription_snapshot s_1 ON (true))
          GROUP BY m.month_start
        )
 SELECT month_start,
    ending_mrr_usd,
    ending_active_subs,
    lag(ending_mrr_usd) OVER (ORDER BY month_start) AS starting_mrr_usd,
    lag(ending_active_subs) OVER (ORDER BY month_start) AS starting_active_subs,
    (ending_mrr_usd - COALESCE(lag(ending_mrr_usd) OVER (ORDER BY month_start), (0)::numeric)) AS net_new_mrr_usd
   FROM spine s
  ORDER BY month_start;


--
-- Name: v_subscription_movements; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_subscription_movements WITH (security_invoker='true') AS
 WITH months AS (
         SELECT (generate_series(date_trunc('month'::text, (now() - '11 mons'::interval)), date_trunc('month'::text, now()), '1 mon'::interval))::date AS month_start
        ), new_subs AS (
         SELECT (date_trunc('month'::text, v_subscription_snapshot.subscription_started_at))::date AS month_start,
            (count(*))::integer AS new_subs,
            COALESCE(sum(v_subscription_snapshot.mrr_usd), (0)::numeric) AS new_mrr_usd
           FROM public.v_subscription_snapshot
          WHERE (v_subscription_snapshot.subscription_started_at IS NOT NULL)
          GROUP BY ((date_trunc('month'::text, v_subscription_snapshot.subscription_started_at))::date)
        ), churn AS (
         SELECT (date_trunc('month'::text, v_subscription_churn_events.canceled_at))::date AS month_start,
            (count(*))::integer AS churned_subs,
            COALESCE(sum(v_subscription_churn_events.lost_mrr_usd), (0)::numeric) AS churned_mrr_usd
           FROM public.v_subscription_churn_events
          WHERE (v_subscription_churn_events.canceled_at IS NOT NULL)
          GROUP BY ((date_trunc('month'::text, v_subscription_churn_events.canceled_at))::date)
        )
 SELECT m.month_start,
    COALESCE(n.new_subs, 0) AS new_subs,
    COALESCE(n.new_mrr_usd, (0)::numeric) AS new_mrr_usd,
    COALESCE(c.churned_subs, 0) AS churned_subs,
    COALESCE(c.churned_mrr_usd, (0)::numeric) AS churned_mrr_usd,
    0 AS expansion_subs,
    (0)::numeric AS expansion_mrr_usd,
    0 AS contraction_subs,
    (0)::numeric AS contraction_mrr_usd,
    'derived'::text AS basis
   FROM ((months m
     LEFT JOIN new_subs n ON ((n.month_start = m.month_start)))
     LEFT JOIN churn c ON ((c.month_start = m.month_start)))
  ORDER BY m.month_start;


--
-- Name: v_exec_mrr_bridge; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_exec_mrr_bridge WITH (security_invoker='true') AS
 SELECT sp.month_start,
    COALESCE(sp.starting_mrr_usd, (0)::numeric) AS starting_mrr_usd,
    COALESCE(mv.new_mrr_usd, (0)::numeric) AS new_mrr_usd,
    COALESCE(mv.expansion_mrr_usd, (0)::numeric) AS expansion_mrr_usd,
    COALESCE(mv.contraction_mrr_usd, (0)::numeric) AS contraction_mrr_usd,
    COALESCE(mv.churned_mrr_usd, (0)::numeric) AS churned_mrr_usd,
    sp.ending_mrr_usd,
    sp.net_new_mrr_usd,
    'derived'::text AS basis
   FROM (public.v_exec_mrr_spine sp
     LEFT JOIN public.v_subscription_movements mv ON ((mv.month_start = sp.month_start)))
  ORDER BY sp.month_start;


--
-- Name: v_bi_exec_mrr_bridge; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_exec_mrr_bridge WITH (security_invoker='true') AS
 SELECT month_start,
    starting_mrr_usd,
    new_mrr_usd,
    expansion_mrr_usd,
    contraction_mrr_usd,
    churned_mrr_usd,
    ending_mrr_usd,
    net_new_mrr_usd,
    basis
   FROM public.v_exec_mrr_bridge;


--
-- Name: v_bi_exec_mrr_spine; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_exec_mrr_spine WITH (security_invoker='true') AS
 SELECT month_start,
    ending_mrr_usd,
    ending_active_subs,
    starting_mrr_usd,
    starting_active_subs,
    net_new_mrr_usd
   FROM public.v_exec_mrr_spine;


--
-- Name: v_subscription_plan_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_subscription_plan_summary WITH (security_invoker='true') AS
 SELECT COALESCE(plan_name, 'unknown'::text) AS plan_name,
    acquisition_type,
    (count(*))::integer AS subscriptions,
    (count(*) FILTER (WHERE (subscription_state = 'active'::text)))::integer AS active_count,
    (count(*) FILTER (WHERE (subscription_state = 'canceled'::text)))::integer AS canceled_count,
    (count(*) FILTER (WHERE (subscription_state = 'past_due'::text)))::integer AS past_due_count,
    (count(*) FILTER (WHERE (mrr_usd IS NOT NULL)))::integer AS subscriptions_with_known_mrr,
    COALESCE(sum(mrr_usd) FILTER (WHERE (subscription_state = 'active'::text)), (0)::numeric) AS active_known_mrr_usd,
    avg(mrr_usd) FILTER (WHERE (subscription_state = 'active'::text)) AS avg_active_known_mrr_usd
   FROM public.v_subscription_snapshot s
  GROUP BY COALESCE(plan_name, 'unknown'::text), acquisition_type;


--
-- Name: v_exec_plan_contribution; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_exec_plan_contribution WITH (security_invoker='true') AS
 WITH totals AS (
         SELECT NULLIF(sum(v_subscription_plan_summary.active_known_mrr_usd), (0)::numeric) AS total_known_mrr
           FROM public.v_subscription_plan_summary
        )
 SELECT plan_name,
    acquisition_type AS stream,
    active_count,
    canceled_count,
    active_known_mrr_usd,
        CASE
            WHEN (( SELECT totals.total_known_mrr
               FROM totals) IS NOT NULL) THEN round((active_known_mrr_usd / ( SELECT totals.total_known_mrr
               FROM totals)), 4)
            ELSE NULL::numeric
        END AS share_of_known_mrr,
    avg_active_known_mrr_usd
   FROM public.v_subscription_plan_summary p
  ORDER BY active_known_mrr_usd DESC NULLS LAST;


--
-- Name: v_bi_exec_plan_contribution; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_exec_plan_contribution WITH (security_invoker='true') AS
 SELECT plan_name,
    stream,
    active_count,
    canceled_count,
    active_known_mrr_usd,
    share_of_known_mrr,
    avg_active_known_mrr_usd
   FROM public.v_exec_plan_contribution;


--
-- Name: v_exec_retention_rates; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_exec_retention_rates WITH (security_invoker='true') AS
 WITH base AS (
         SELECT sp.month_start,
            sp.starting_mrr_usd,
            sp.starting_active_subs,
            sp.ending_mrr_usd,
            COALESCE(mv.churned_mrr_usd, (0)::numeric) AS churned_mrr_usd,
            COALESCE(mv.churned_subs, 0) AS churned_subs,
            COALESCE(mv.new_mrr_usd, (0)::numeric) AS new_mrr_usd
           FROM (public.v_exec_mrr_spine sp
             LEFT JOIN public.v_subscription_movements mv ON ((mv.month_start = sp.month_start)))
        )
 SELECT month_start,
    starting_mrr_usd,
    starting_active_subs,
    churned_mrr_usd,
    churned_subs,
        CASE
            WHEN (COALESCE(starting_mrr_usd, (0)::numeric) > (0)::numeric) THEN round((churned_mrr_usd / starting_mrr_usd), 4)
            ELSE NULL::numeric
        END AS revenue_churn_rate,
        CASE
            WHEN (COALESCE(starting_active_subs, 0) > 0) THEN round(((churned_subs)::numeric / (starting_active_subs)::numeric), 4)
            ELSE NULL::numeric
        END AS logo_churn_rate,
        CASE
            WHEN (COALESCE(starting_mrr_usd, (0)::numeric) > (0)::numeric) THEN round(((starting_mrr_usd - churned_mrr_usd) / starting_mrr_usd), 4)
            ELSE NULL::numeric
        END AS gross_revenue_retention,
        CASE
            WHEN (COALESCE(starting_mrr_usd, (0)::numeric) > (0)::numeric) THEN round(((starting_mrr_usd - churned_mrr_usd) / starting_mrr_usd), 4)
            ELSE NULL::numeric
        END AS net_revenue_retention,
    'derived (expansion/contraction not yet tracked)'::text AS basis
   FROM base
  ORDER BY month_start;


--
-- Name: v_bi_exec_retention_rates; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_exec_retention_rates WITH (security_invoker='true') AS
 SELECT month_start,
    starting_mrr_usd,
    starting_active_subs,
    churned_mrr_usd,
    churned_subs,
    revenue_churn_rate,
    logo_churn_rate,
    gross_revenue_retention,
    net_revenue_retention,
    basis
   FROM public.v_exec_retention_rates;


