--
-- Name: v_wl_partner_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_wl_partner_readiness AS
 SELECT p.id AS partner_id,
    p.partner_slug,
    p.company_name,
    p.status AS partner_status,
    p.tier,
    (b.id IS NOT NULL) AS has_branding,
    (b.custom_domain IS NOT NULL) AS has_custom_domain,
    COALESCE(b.cname_status, 'pending'::text) AS cname_status,
    (COALESCE(b.cname_status, 'pending'::text) = 'verified'::text) AS domain_verified,
    (COALESCE(alias_counts.alias_count, (0)::bigint))::integer AS alias_count,
    (COALESCE(client_counts.total_clients, (0)::bigint))::integer AS total_clients,
    (COALESCE(client_counts.active_clients, (0)::bigint))::integer AS active_clients,
    (COALESCE(client_counts.portal_provisioned, (0)::bigint))::integer AS clients_with_portal,
        CASE
            WHEN (p.status <> 'active'::text) THEN 'pending'::text
            WHEN (b.id IS NULL) THEN 'configured'::text
            WHEN (b.custom_domain IS NULL) THEN 'branded'::text
            WHEN (COALESCE(b.cname_status, 'pending'::text) <> 'verified'::text) THEN 'domain_pending'::text
            WHEN (COALESCE(client_counts.active_clients, (0)::bigint) = 0) THEN 'domain_ready'::text
            ELSE 'live'::text
        END AS readiness_state
   FROM (((public.white_label_partners p
     LEFT JOIN public.white_label_branding b ON ((b.partner_id = p.id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_clients,
            count(*) FILTER (WHERE (c.status = 'active'::text)) AS active_clients,
            count(*) FILTER (WHERE (c.user_id IS NOT NULL)) AS portal_provisioned
           FROM public.white_label_clients c
          WHERE (c.partner_id = p.id)) client_counts ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS alias_count
           FROM public.white_label_domain_aliases a
          WHERE (a.partner_id = p.id)) alias_counts ON (true));


--
-- Name: VIEW v_wl_partner_readiness; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_wl_partner_readiness IS 'Phase 6: per-partner activation/readiness rollup (pending → configured → branded → domain_ready → live).';


--
-- Name: v_intelligence_executive_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_intelligence_executive_summary AS
 SELECT ( SELECT count(*) AS count
           FROM public.leads
          WHERE (leads.status <> ALL (ARRAY['converted'::text, 'lost'::text, 'disqualified'::text]))) AS active_leads,
    ( SELECT count(*) AS count
           FROM public.leads
          WHERE (leads.won_at >= (now() - '30 days'::interval))) AS leads_won_30d,
    ( SELECT count(*) AS count
           FROM public.leads
          WHERE (leads.created_at >= (now() - '30 days'::interval))) AS leads_new_30d,
    ( SELECT count(*) AS count
           FROM public.internal_fulfillment_intakes
          WHERE (internal_fulfillment_intakes.status <> ALL (ARRAY['activated'::text, 'closed'::text]))) AS intakes_open,
    ( SELECT count(*) AS count
           FROM public.internal_fulfillment_intakes
          WHERE (internal_fulfillment_intakes.activated_at >= (now() - '30 days'::interval))) AS intakes_activated_30d,
    ( SELECT count(*) AS count
           FROM public.v_call_flow_receptionist_readiness
          WHERE (v_call_flow_receptionist_readiness.readiness_state = 'live'::text)) AS receptionists_live,
    ( SELECT count(*) AS count
           FROM public.v_call_flow_receptionist_readiness
          WHERE (v_call_flow_receptionist_readiness.readiness_state = ANY (ARRAY['awaiting_script_publish'::text, 'awaiting_number'::text]))) AS receptionists_blocked,
    ( SELECT count(*) AS count
           FROM public.v_wl_partner_readiness
          WHERE (v_wl_partner_readiness.readiness_state = 'live'::text)) AS wl_partners_live,
    ( SELECT count(*) AS count
           FROM public.v_wl_partner_readiness) AS wl_partners_total,
    ( SELECT count(*) AS count
           FROM public.blog_posts
          WHERE ((blog_posts.status = 'published'::text) AND (blog_posts.published_at >= (now() - '30 days'::interval)))) AS blog_published_30d,
    ( SELECT count(*) AS count
           FROM public.automation_recommendations
          WHERE (automation_recommendations.status = 'open'::text)) AS recs_open,
    ( SELECT count(*) AS count
           FROM public.automation_recommendations
          WHERE ((automation_recommendations.status = 'open'::text) AND (automation_recommendations.severity = ANY (ARRAY['warn'::text, 'critical'::text])))) AS recs_warn_or_critical,
    ( SELECT count(*) AS count
           FROM public.automation_recommendations
          WHERE (automation_recommendations.resolved_at >= (now() - '30 days'::interval))) AS recs_resolved_30d,
    now() AS computed_at;


--
-- Name: v_bi_executive_kpi; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_executive_kpi WITH (security_invoker='true') AS
 SELECT computed_at AS as_of,
    active_leads,
