    recs_warn_or_critical,
    recs_resolved_30d
   FROM public.v_intelligence_executive_summary;


--
-- Name: v_pricing_experiment_results; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pricing_experiment_results WITH (security_invoker='true') AS
 SELECT e.id AS experiment_id,
    e.name AS experiment_name,
    e.status AS experiment_status,
    a.variant_key,
    count(a.id) AS assignments,
    count(DISTINCT a.lead_id) AS leads_assigned,
    count(DISTINCT a.visitor_key) AS visitors_assigned,
    count(DISTINCT s.lead_id) FILTER (WHERE (s.subscription_state = ANY (ARRAY['active'::text, 'past_due'::text, 'canceled'::text]))) AS leads_converted,
    count(DISTINCT s.lead_id) FILTER (WHERE (s.subscription_state = 'active'::text)) AS active_subs,
    COALESCE(sum(s.mrr_usd) FILTER (WHERE (s.subscription_state = 'active'::text)), (0)::numeric) AS active_known_mrr_usd,
        CASE
            WHEN (count(DISTINCT s.lead_id) FILTER (WHERE ((s.subscription_state = 'active'::text) AND (s.mrr_usd IS NOT NULL))) > 0) THEN (COALESCE(sum(s.mrr_usd) FILTER (WHERE (s.subscription_state = 'active'::text)), (0)::numeric) / (NULLIF(count(DISTINCT s.lead_id) FILTER (WHERE ((s.subscription_state = 'active'::text) AND (s.mrr_usd IS NOT NULL))), 0))::numeric)
            ELSE NULL::numeric
        END AS avg_active_known_mrr_usd
   FROM ((public.pricing_experiments e
     LEFT JOIN public.pricing_experiment_assignments a ON ((a.experiment_id = e.id)))
     LEFT JOIN public.v_subscription_snapshot s ON ((s.lead_id = a.lead_id)))
  GROUP BY e.id, e.name, e.status, a.variant_key;


--
-- Name: v_experiment_allocation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_experiment_allocation WITH (security_invoker='true') AS
 WITH base AS (
         SELECT r.experiment_id,
            r.experiment_name,
            r.experiment_status,
            r.variant_key,
            r.leads_assigned,
            r.leads_converted,
            e.allocation_mode,
            e.bandit_algorithm,
            e.max_exposure_per_variant,
            e.kill_switch_active,
            e.min_sample_per_variant
           FROM (public.v_pricing_experiment_results r
             JOIN public.pricing_experiments e ON ((e.id = r.experiment_id)))
        )
 SELECT experiment_id,
    experiment_name,
    experiment_status,
    allocation_mode,
    bandit_algorithm,
    kill_switch_active,
    max_exposure_per_variant,
    min_sample_per_variant,
    variant_key,
    leads_assigned,
    leads_converted,
    ((1 + leads_converted))::numeric AS posterior_alpha,
    ((1 + GREATEST((leads_assigned - leads_converted), (0)::bigint)))::numeric AS posterior_beta,
        CASE
            WHEN (leads_assigned > 0) THEN ((leads_converted)::numeric / (leads_assigned)::numeric)
            ELSE NULL::numeric
        END AS conversion_rate,
    (((1 + leads_converted))::numeric / NULLIF((((1 + leads_converted) + (1 + GREATEST((leads_assigned - leads_converted), (0)::bigint))))::numeric, (0)::numeric)) AS posterior_mean,
        CASE
            WHEN ((max_exposure_per_variant IS NOT NULL) AND (leads_assigned >= max_exposure_per_variant)) THEN true
            ELSE false
        END AS max_exposure_reached
   FROM base b;


--
-- Name: v_bi_experiment_allocation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_experiment_allocation WITH (security_invoker='true') AS
 SELECT experiment_id,
    experiment_name,
    experiment_status,
    allocation_mode,
    bandit_algorithm,
    kill_switch_active,
    max_exposure_per_variant,
    min_sample_per_variant,
    variant_key,
    leads_assigned,
    leads_converted,
    posterior_alpha,
    posterior_beta,
    conversion_rate,
    posterior_mean,
    max_exposure_reached
   FROM public.v_experiment_allocation;


--
-- Name: v_experiment_decisions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_experiment_decisions WITH (security_invoker='true') AS
 WITH base AS (
         SELECT r.experiment_id,
            r.experiment_name,
            r.experiment_status,
            r.variant_key,
            r.assignments,
            r.leads_assigned,
            r.leads_converted,
            r.active_subs,
            r.active_known_mrr_usd,
            r.avg_active_known_mrr_usd,
            e.min_sample_per_variant,
            e.primary_metric,
            e.variants,
            e.allocation_mode,
            e.bandit_algorithm,
            e.max_exposure_per_variant,
            e.kill_switch_active,
            e.sequential_looks,
            e.loss_threshold_pct
           FROM (public.v_pricing_experiment_results r
             JOIN public.pricing_experiments e ON ((e.id = r.experiment_id)))
        ), control AS (
         SELECT base.experiment_id,
            base.leads_assigned AS c_n,
            base.leads_converted AS c_x
           FROM base
          WHERE (base.variant_key = 'control'::text)
        ), joined AS (
         SELECT b.experiment_id,
            b.experiment_name,
            b.experiment_status,
            b.variant_key,
            b.assignments,
            b.leads_assigned,
            b.leads_converted,
            b.active_subs,
            b.active_known_mrr_usd,
            b.avg_active_known_mrr_usd,
            b.min_sample_per_variant,
            b.primary_metric,
            b.variants,
            b.allocation_mode,
            b.bandit_algorithm,
            b.max_exposure_per_variant,
            b.kill_switch_active,
            b.sequential_looks,
            b.loss_threshold_pct,
            c.c_n,
            c.c_x,
                CASE
                    WHEN (b.leads_assigned > 0) THEN ((b.leads_converted)::numeric / (b.leads_assigned)::numeric)
                    ELSE NULL::numeric
                END AS p_variant,
                CASE
                    WHEN (c.c_n > 0) THEN ((c.c_x)::numeric / (c.c_n)::numeric)
                    ELSE NULL::numeric
                END AS p_control
           FROM (base b
             LEFT JOIN control c ON ((c.experiment_id = b.experiment_id)))
        ), scored AS (
         SELECT j.experiment_id,
            j.experiment_name,
            j.experiment_status,
            j.variant_key,
            j.assignments,
            j.leads_assigned,
            j.leads_converted,
            j.active_subs,
            j.active_known_mrr_usd,
            j.avg_active_known_mrr_usd,
            j.min_sample_per_variant,
            j.primary_metric,
            j.variants,
            j.allocation_mode,
            j.bandit_algorithm,
            j.max_exposure_per_variant,
            j.kill_switch_active,
            j.sequential_looks,
            j.loss_threshold_pct,
            j.c_n,
            j.c_x,
            j.p_variant,
            j.p_control,
                CASE
                    WHEN (j.variant_key = 'control'::text) THEN NULL::numeric
                    WHEN ((j.p_variant IS NULL) OR (j.p_control IS NULL)) THEN NULL::numeric
                    WHEN ((((j.p_variant * ((1)::numeric - j.p_variant)) / (NULLIF(j.leads_assigned, 0))::numeric) + ((j.p_control * ((1)::numeric - j.p_control)) / (NULLIF(j.c_n, 0))::numeric)) <= (0)::numeric) THEN NULL::numeric
                    ELSE ((j.p_variant - j.p_control) / sqrt((((j.p_variant * ((1)::numeric - j.p_variant)) / (NULLIF(j.leads_assigned, 0))::numeric) + ((j.p_control * ((1)::numeric - j.p_control)) / (NULLIF(j.c_n, 0))::numeric))))
                END AS z_score
           FROM joined j
        ), seq_bound AS (
         SELECT s_1.experiment_id,
            s_1.experiment_name,
            s_1.experiment_status,
            s_1.variant_key,
            s_1.assignments,
            s_1.leads_assigned,
            s_1.leads_converted,
            s_1.active_subs,
            s_1.active_known_mrr_usd,
            s_1.avg_active_known_mrr_usd,
            s_1.min_sample_per_variant,
            s_1.primary_metric,
            s_1.variants,
            s_1.allocation_mode,
            s_1.bandit_algorithm,
            s_1.max_exposure_per_variant,
            s_1.kill_switch_active,
            s_1.sequential_looks,
            s_1.loss_threshold_pct,
            s_1.c_n,
            s_1.c_x,
            s_1.p_variant,
            s_1.p_control,
            s_1.z_score,
                CASE s_1.sequential_looks
                    WHEN 1 THEN 1.96
                    WHEN 2 THEN 2.24
                    WHEN 3 THEN 2.39
                    WHEN 4 THEN 2.49
                    WHEN 5 THEN 2.57
                    WHEN 6 THEN 2.64
                    WHEN 7 THEN 2.69
                    WHEN 8 THEN 2.74
                    WHEN 9 THEN 2.78
                    ELSE 2.81
                END AS sequential_z_critical
           FROM scored s_1
        )
 SELECT experiment_id,
    experiment_name,
    experiment_status,
    allocation_mode,
    bandit_algorithm,
    kill_switch_active,
    max_exposure_per_variant,
    variant_key,
    assignments,
    leads_assigned,
    leads_converted,
    active_subs,
    active_known_mrr_usd,
    avg_active_known_mrr_usd,
    min_sample_per_variant,
    p_variant AS conversion_rate,
    p_control AS control_conversion_rate,
    z_score,
    sequential_z_critical,
        CASE
            WHEN kill_switch_active THEN 'killed'::text
            WHEN ((max_exposure_per_variant IS NOT NULL) AND (leads_assigned >= max_exposure_per_variant)) THEN 'max_exposure_reached'::text
            WHEN (variant_key = 'control'::text) THEN 'baseline'::text
            WHEN (leads_assigned < min_sample_per_variant) THEN 'insufficient_sample'::text
            WHEN (z_score IS NULL) THEN 'directional_only'::text
            WHEN ((allocation_mode = 'sequential'::text) AND (z_score >= sequential_z_critical)) THEN 'early_stop_winner'::text
            WHEN ((allocation_mode = 'sequential'::text) AND (z_score <= (- sequential_z_critical))) THEN 'early_stop_futility'::text
            WHEN ((abs(z_score) >= 1.96) AND (z_score > (0)::numeric)) THEN 'statistically_supported_winner'::text
            WHEN ((abs(z_score) >= 1.96) AND (z_score < (0)::numeric)) THEN 'statistically_supported_loser'::text
            ELSE 'directional_only'::text
        END AS confidence_label,
        CASE
            WHEN kill_switch_active THEN 'no_action'::text
            WHEN (experiment_status <> ALL (ARRAY['active'::text, 'live'::text])) THEN 'no_action'::text
            WHEN (variant_key = 'control'::text) THEN 'baseline'::text
            WHEN ((max_exposure_per_variant IS NOT NULL) AND (leads_assigned >= max_exposure_per_variant) AND (z_score IS NOT NULL) AND (z_score >= 1.96)) THEN 'promote_winner'::text
            WHEN ((max_exposure_per_variant IS NOT NULL) AND (leads_assigned >= max_exposure_per_variant)) THEN 'archive_inconclusive'::text
            WHEN ((allocation_mode = 'sequential'::text) AND (z_score IS NOT NULL) AND (z_score >= sequential_z_critical)) THEN 'promote_winner'::text
            WHEN ((allocation_mode = 'sequential'::text) AND (z_score IS NOT NULL) AND (z_score <= (- sequential_z_critical))) THEN 'archive_loser'::text
            WHEN (leads_assigned < min_sample_per_variant) THEN 'keep_running'::text
            WHEN ((z_score IS NOT NULL) AND (z_score >= 1.96)) THEN 'promote_winner'::text
            WHEN ((z_score IS NOT NULL) AND (z_score <= '-1.96'::numeric)) THEN 'archive_loser'::text
            ELSE 'archive_inconclusive'::text
        END AS recommendation
   FROM seq_bound s;


--
-- Name: v_bi_experiment_decisions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_experiment_decisions WITH (security_invoker='true') AS
 SELECT experiment_id,
    experiment_name,
    experiment_status,
    allocation_mode,
    bandit_algorithm,
    kill_switch_active,
    max_exposure_per_variant,
    variant_key,
    assignments,
    leads_assigned,
    leads_converted,
    active_subs,
    active_known_mrr_usd,
    avg_active_known_mrr_usd,
    min_sample_per_variant,
    conversion_rate,
    control_conversion_rate,
    z_score,
    sequential_z_critical,
    confidence_label,
    recommendation
   FROM public.v_experiment_decisions;


