    subscription_state,
    (count(*))::integer AS subscriptions,
    (count(*) FILTER (WHERE (mrr_usd IS NOT NULL)))::integer AS subscriptions_with_known_mrr,
    (count(*) FILTER (WHERE (mrr_usd IS NULL)))::integer AS subscriptions_unknown_mrr,
    COALESCE(sum(mrr_usd), (0)::numeric) AS known_mrr_usd
   FROM public.v_subscription_snapshot s
  GROUP BY acquisition_type, subscription_state;


--
-- Name: v_forecast_assumption_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_assumption_performance WITH (security_invoker='true') AS
 WITH recent AS (
         SELECT avg(v_subscription_movements.new_mrr_usd) AS avg_new_mrr,
            avg(v_subscription_movements.churned_mrr_usd) AS avg_churn_mrr,
            avg(GREATEST((COALESCE(v_subscription_movements.expansion_mrr_usd, (0)::numeric) - COALESCE(v_subscription_movements.contraction_mrr_usd, (0)::numeric)), (0)::numeric)) AS avg_net_expansion_mrr,
            count(*) AS month_count
           FROM public.v_subscription_movements
          WHERE ((v_subscription_movements.month_start >= (date_trunc('month'::text, now()) - '6 mons'::interval)) AND (v_subscription_movements.month_start < date_trunc('month'::text, now())))
        ), base AS (
         SELECT COALESCE(sum(v_subscription_mrr_summary.known_mrr_usd), (0)::numeric) AS active_mrr
           FROM public.v_subscription_mrr_summary
        )
 SELECT fa.assumption_key,
    fa.baseline_monthly_churn_rate AS configured_churn_rate,
    fa.baseline_monthly_expansion_rate AS configured_expansion_rate,
    fa.new_business_mrr_direct AS configured_new_biz_direct,
    fa.new_business_mrr_wl AS configured_new_biz_wl,
    (fa.new_business_mrr_direct + fa.new_business_mrr_wl) AS configured_new_biz_total,
    r.month_count AS sample_months,
    r.avg_new_mrr AS realized_avg_new_biz,
    r.avg_churn_mrr AS realized_avg_churn_amount,
    r.avg_net_expansion_mrr AS realized_avg_expansion_amount,
        CASE
            WHEN (b.active_mrr > (0)::numeric) THEN (r.avg_churn_mrr / b.active_mrr)
            ELSE NULL::numeric
        END AS realized_churn_rate,
        CASE
            WHEN (b.active_mrr > (0)::numeric) THEN (r.avg_net_expansion_mrr / b.active_mrr)
            ELSE NULL::numeric
        END AS realized_expansion_rate,
        CASE
            WHEN (b.active_mrr > (0)::numeric) THEN ((r.avg_churn_mrr / b.active_mrr) - fa.baseline_monthly_churn_rate)
            ELSE NULL::numeric
        END AS churn_calibration_delta,
        CASE
            WHEN (b.active_mrr > (0)::numeric) THEN ((r.avg_net_expansion_mrr / b.active_mrr) - fa.baseline_monthly_expansion_rate)
            ELSE NULL::numeric
        END AS expansion_calibration_delta,
    (r.avg_new_mrr - (fa.new_business_mrr_direct + fa.new_business_mrr_wl)) AS new_biz_calibration_delta
   FROM ((public.forecast_assumptions fa
     CROSS JOIN recent r)
     CROSS JOIN base b)
  WHERE (fa.assumption_key = 'default'::text);


--
-- Name: v_bi_forecast_assumption_performance; Type: VIEW; Schema: public; Owner: -
