--
-- Name: v_forecast_stage_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_stage_performance WITH (security_invoker='true') AS
 WITH closed_deals AS (
         SELECT renewal_expansion_deals.deal_type,
            count(*) FILTER (WHERE (renewal_expansion_deals.status = 'won'::public.deal_status)) AS won_count,
            count(*) FILTER (WHERE (renewal_expansion_deals.status = 'lost'::public.deal_status)) AS lost_count,
            count(*) FILTER (WHERE (renewal_expansion_deals.status = ANY (ARRAY['won'::public.deal_status, 'lost'::public.deal_status]))) AS decided_count
           FROM public.renewal_expansion_deals
          WHERE ((renewal_expansion_deals.updated_at >= (now() - '180 days'::interval)) AND (renewal_expansion_deals.status = ANY (ARRAY['won'::public.deal_status, 'lost'::public.deal_status])))
          GROUP BY renewal_expansion_deals.deal_type
        ), configured AS (
         SELECT (forecast_stage_probabilities.deal_type)::text AS deal_type,
            avg(forecast_stage_probabilities.probability) AS avg_configured_probability,
            count(*) AS stage_count
           FROM public.forecast_stage_probabilities
          GROUP BY forecast_stage_probabilities.deal_type
        )
 SELECT c.deal_type,
    c.avg_configured_probability,
    c.stage_count,
    COALESCE(cd.decided_count, (0)::bigint) AS sample_size,
    COALESCE(cd.won_count, (0)::bigint) AS won_count,
    COALESCE(cd.lost_count, (0)::bigint) AS lost_count,
        CASE
            WHEN (COALESCE(cd.decided_count, (0)::bigint) = 0) THEN NULL::numeric
            ELSE ((cd.won_count)::numeric / (cd.decided_count)::numeric)
        END AS realized_win_rate,
        CASE
            WHEN (COALESCE(cd.decided_count, (0)::bigint) = 0) THEN NULL::numeric
            ELSE (((cd.won_count)::numeric / (cd.decided_count)::numeric) - c.avg_configured_probability)
        END AS calibration_delta
   FROM (configured c
     LEFT JOIN closed_deals cd ON (((cd.deal_type)::text = c.deal_type)));


--
-- Name: v_bi_forecast_stage_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_forecast_stage_performance WITH (security_invoker='true') AS
 SELECT deal_type,
    avg_configured_probability,
    stage_count,
    sample_size,
    won_count,
    lost_count,
    realized_win_rate,
    calibration_delta
   FROM public.v_forecast_stage_performance;


