--
-- Name: v_forecast_vs_actuals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_forecast_vs_actuals WITH (security_invoker='true') AS
 WITH expanded AS (
         SELECT s.id AS snapshot_id,
            s.label AS snapshot_label,
            s.generated_at,
            (row_elem.value ->> 'period'::text) AS period,
            ((row_elem.value ->> 'month_start'::text))::date AS month_start,
            ((row_elem.value ->> 'month_index'::text))::integer AS month_index,
            (NULLIF((row_elem.value ->> 'projected_base_mrr'::text), ''::text))::numeric AS forecast_base_mrr,
            (NULLIF((row_elem.value ->> 'baseline_churn_amount'::text), ''::text))::numeric AS forecast_churn,
            (NULLIF((row_elem.value ->> 'baseline_expansion_amount'::text), ''::text))::numeric AS forecast_expansion,
            (NULLIF((row_elem.value ->> 'new_business_mrr'::text), ''::text))::numeric AS forecast_new_business,
            (NULLIF((row_elem.value ->> 'projected_ending_mrr'::text), ''::text))::numeric AS forecast_ending_mrr
           FROM (public.forecast_snapshots s
             CROSS JOIN LATERAL jsonb_array_elements(s.payload) row_elem(value))
        )
 SELECT e.snapshot_id,
    e.snapshot_label,
    e.generated_at,
    e.period,
    e.month_start,
    e.month_index,
    e.forecast_new_business,
    e.forecast_churn,
    e.forecast_expansion,
    e.forecast_ending_mrr,
    m.new_mrr_usd AS actual_new_business,
    m.churned_mrr_usd AS actual_churn,
    GREATEST((COALESCE(m.expansion_mrr_usd, (0)::numeric) - COALESCE(m.contraction_mrr_usd, (0)::numeric)), (0)::numeric) AS actual_net_expansion,
    (m.new_mrr_usd - COALESCE(e.forecast_new_business, (0)::numeric)) AS variance_new_business,
    (COALESCE(e.forecast_churn, (0)::numeric) - m.churned_mrr_usd) AS variance_churn,
    ((COALESCE(m.expansion_mrr_usd, (0)::numeric) - COALESCE(m.contraction_mrr_usd, (0)::numeric)) - COALESCE(e.forecast_expansion, (0)::numeric)) AS variance_expansion,
        CASE
            WHEN (COALESCE(e.forecast_new_business, (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE ((m.new_mrr_usd - e.forecast_new_business) / e.forecast_new_business)
        END AS pct_variance_new_business,
        CASE
            WHEN (COALESCE(e.forecast_churn, (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE ((e.forecast_churn - m.churned_mrr_usd) / e.forecast_churn)
        END AS pct_variance_churn,
        CASE
            WHEN (COALESCE(e.forecast_expansion, (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE (((COALESCE(m.expansion_mrr_usd, (0)::numeric) - COALESCE(m.contraction_mrr_usd, (0)::numeric)) - e.forecast_expansion) / e.forecast_expansion)
        END AS pct_variance_expansion
   FROM (expanded e
     JOIN public.v_subscription_movements m ON (((date_trunc('month'::text, (m.month_start)::timestamp with time zone))::date = e.month_start)))
  WHERE (e.month_start < (date_trunc('month'::text, now()))::date);


--
-- Name: v_bi_forecast_vs_actuals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_forecast_vs_actuals WITH (security_invoker='true') AS
 SELECT snapshot_id,
    snapshot_label,
    generated_at,
    period,
    month_start,
    month_index,
    forecast_new_business,
    forecast_churn,
    forecast_expansion,
    forecast_ending_mrr,
    actual_new_business,
    actual_churn,
    actual_net_expansion,
    variance_new_business,
    variance_churn,
    variance_expansion,
    pct_variance_new_business,
    pct_variance_churn,
    pct_variance_expansion
   FROM public.v_forecast_vs_actuals;


--
-- Name: v_growth_attribution_lead; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_growth_attribution_lead WITH (security_invoker='true') AS
 SELECT l.id AS lead_id,
    l.created_at AS lead_created_at,
    (date_trunc('month'::text, l.created_at))::date AS cohort_month,
    COALESCE(NULLIF(l.source, ''::text), 'unknown'::text) AS raw_source,
    public.growth_normalize_channel(l.source) AS channel,
        CASE
            WHEN (i.partner_id IS NOT NULL) THEN 'wl'::text
            ELSE 'direct'::text
        END AS acquisition_type,
    i.partner_id AS wl_partner_id,
    l.pipeline_stage,
    l.lead_temperature,
    l.country,
    l.billing_currency,
    l.service_type,
    (lc.lead_id IS NOT NULL) AS converted,
    lc.converted_at,
    i.id AS intake_id,
    i.activated_at,
        CASE
            WHEN (lc.converted_at IS NOT NULL) THEN (EXTRACT(epoch FROM (lc.converted_at - l.created_at)) / 86400.0)
            ELSE NULL::numeric
        END AS days_to_convert
   FROM ((public.leads l
     LEFT JOIN public.lead_conversions lc ON ((lc.lead_id = l.id)))
     LEFT JOIN public.internal_fulfillment_intakes i ON (((i.client_lead_id = l.id) OR (i.lead_id = l.id))));


--
-- Name: VIEW v_growth_attribution_lead; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_growth_attribution_lead IS 'Phase 13: per-lead canonical attribution. SECURITY INVOKER; relies on leads RLS (admin/supervisor visible). Channel is normalized via growth_normalize_channel. acquisition_type is honest binary (direct vs wl) based on intake.partner_id presence; multi-touch is intentionally NOT modeled.';


--
-- Name: v_growth_channel_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_growth_channel_summary WITH (security_invoker='true') AS
 SELECT channel,
    (count(*))::integer AS leads,
    (count(*) FILTER (WHERE converted))::integer AS conversions,
    (count(*) FILTER (WHERE (acquisition_type = 'direct'::text)))::integer AS direct_leads,
    (count(*) FILTER (WHERE (acquisition_type = 'wl'::text)))::integer AS wl_leads,
        CASE
            WHEN (count(*) > 0) THEN round(((100.0 * (count(*) FILTER (WHERE converted))::numeric) / (count(*))::numeric), 2)
            ELSE (0)::numeric
        END AS conversion_rate_pct,
    round(avg(days_to_convert) FILTER (WHERE (days_to_convert IS NOT NULL)), 1) AS avg_days_to_convert,
    (count(*) FILTER (WHERE (activated_at IS NOT NULL)))::integer AS activations
   FROM public.v_growth_attribution_lead
  WHERE (lead_created_at >= (now() - '365 days'::interval))
  GROUP BY channel
  ORDER BY ((count(*))::integer) DESC;


--
-- Name: VIEW v_growth_channel_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_growth_channel_summary IS 'Phase 13: channel performance, last 365 days. Honest first-touch only; no fabricated multi-touch attribution.';


--
-- Name: v_bi_growth_channel_summary; Type: VIEW; Schema: public; Owner: -
