    avg_days_to_convert,
    activations
   FROM public.v_growth_channel_summary;


--
-- Name: VIEW v_bi_growth_channel_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_bi_growth_channel_summary IS 'Phase 13 BI mirror — admin/RLS-scoped channel performance.';


--
-- Name: v_growth_cohort_lead_month; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_growth_cohort_lead_month WITH (security_invoker='true') AS
 SELECT cohort_month,
    (count(*))::integer AS leads,
    (count(*) FILTER (WHERE converted))::integer AS conversions,
    (count(*) FILTER (WHERE (activated_at IS NOT NULL)))::integer AS activations,
    (count(*) FILTER (WHERE (acquisition_type = 'direct'::text)))::integer AS direct_leads,
    (count(*) FILTER (WHERE (acquisition_type = 'wl'::text)))::integer AS wl_leads,
        CASE
            WHEN (count(*) > 0) THEN round(((100.0 * (count(*) FILTER (WHERE converted))::numeric) / (count(*))::numeric), 2)
            ELSE (0)::numeric
        END AS conversion_rate_pct,
        CASE
            WHEN (count(*) > 0) THEN round(((100.0 * (count(*) FILTER (WHERE (activated_at IS NOT NULL)))::numeric) / (count(*))::numeric), 2)
            ELSE (0)::numeric
        END AS activation_rate_pct
   FROM public.v_growth_attribution_lead
  WHERE (cohort_month >= (date_trunc('month'::text, (now() - '1 year'::interval)))::date)
  GROUP BY cohort_month
  ORDER BY cohort_month DESC;


