--
-- Name: v_growth_direct_vs_wl; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_growth_direct_vs_wl WITH (security_invoker='true') AS
 SELECT acquisition_type,
    (count(*))::integer AS leads,
    (count(*) FILTER (WHERE converted))::integer AS conversions,
    (count(*) FILTER (WHERE (activated_at IS NOT NULL)))::integer AS activations,
        CASE
            WHEN (count(*) > 0) THEN round(((100.0 * (count(*) FILTER (WHERE converted))::numeric) / (count(*))::numeric), 2)
            ELSE (0)::numeric
        END AS conversion_rate_pct,
        CASE
            WHEN (count(*) > 0) THEN round(((100.0 * (count(*) FILTER (WHERE (activated_at IS NOT NULL)))::numeric) / (count(*))::numeric), 2)
            ELSE (0)::numeric
        END AS activation_rate_pct,
    round(avg(days_to_convert) FILTER (WHERE (days_to_convert IS NOT NULL)), 1) AS avg_days_to_convert
   FROM public.v_growth_attribution_lead
  WHERE (lead_created_at >= (now() - '365 days'::interval))
  GROUP BY acquisition_type
  ORDER BY ((count(*))::integer) DESC;


