--
-- Name: v_gtm_target_variance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_gtm_target_variance WITH (security_invoker='true') AS
 SELECT t.period,
    t.scope,
    t.target_new_business_mrr,
    t.target_nrr,
    t.target_renewal_rate,
    (COALESCE(f.new_business_mrr_direct, (0)::numeric) + COALESCE(f.new_business_mrr_wl, (0)::numeric)) AS forecast_new_business_mrr,
        CASE
            WHEN ((t.target_new_business_mrr IS NULL) OR (t.target_new_business_mrr = (0)::numeric)) THEN NULL::numeric
            ELSE round((((COALESCE(f.new_business_mrr_direct, (0)::numeric) + COALESCE(f.new_business_mrr_wl, (0)::numeric)) - t.target_new_business_mrr) / t.target_new_business_mrr), 4)
        END AS new_business_variance_pct,
    f.projected_ending_mrr
   FROM (public.gtm_targets t
     LEFT JOIN public.v_forecast_assembled f ON (((date_trunc('month'::text, (f.month_start)::timestamp with time zone))::date = (date_trunc('month'::text, (t.period)::timestamp with time zone))::date)))
  ORDER BY t.period, t.scope;


--
-- Name: v_bi_gtm_target_variance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_gtm_target_variance WITH (security_invoker='true') AS
 SELECT period,
    scope,
    target_new_business_mrr,
    target_nrr,
    target_renewal_rate,
    forecast_new_business_mrr,
    new_business_variance_pct,
    projected_ending_mrr
   FROM public.v_gtm_target_variance;


