--
-- Name: wl_partner_usage_summary; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wl_partner_usage_summary (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_id uuid NOT NULL,
    billing_period_start date NOT NULL,
    billing_period_end date NOT NULL,
    total_minutes_all_clients numeric DEFAULT 0 NOT NULL,
    total_calls_all_clients integer DEFAULT 0 NOT NULL,
    active_client_count integer DEFAULT 0 NOT NULL,
    volume_discount_active boolean DEFAULT false NOT NULL,
    volume_discount_rate numeric,
