);


--
-- Name: v_wl_partner_economics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_wl_partner_economics WITH (security_invoker='true') AS
 WITH client_counts AS (
         SELECT white_label_clients.partner_id,
            (count(*))::integer AS total_clients,
            (count(*) FILTER (WHERE (white_label_clients.status = 'active'::text)))::integer AS active_clients
           FROM public.white_label_clients
          GROUP BY white_label_clients.partner_id
        ), acq_cost AS (
         SELECT a.wl_partner_id AS partner_id,
            sum(sc.commission_amount) FILTER (WHERE (sc.status = ANY (ARRAY['approved'::text, 'paid'::text]))) AS known_acq_cost_usd,
            count(sc.id) FILTER (WHERE (sc.status = ANY (ARRAY['approved'::text, 'paid'::text]))) AS commission_events
           FROM (public.v_growth_attribution_lead a
             LEFT JOIN public.sales_commissions sc ON ((sc.lead_id = a.lead_id)))
          WHERE (a.wl_partner_id IS NOT NULL)
          GROUP BY a.wl_partner_id
        ), servicing AS (
         SELECT DISTINCT ON (wl_partner_usage_summary.partner_id) wl_partner_usage_summary.partner_id,
            (COALESCE(wl_partner_usage_summary.total_wholesale_cost, (0)::numeric) + COALESCE(wl_partner_usage_summary.total_campaign_fees, (0)::numeric)) AS servicing_cost_proxy_usd,
            wl_partner_usage_summary.billing_period_start AS servicing_period_start,
            wl_partner_usage_summary.billing_period_end AS servicing_period_end
           FROM public.wl_partner_usage_summary
          ORDER BY wl_partner_usage_summary.partner_id, wl_partner_usage_summary.billing_period_start DESC
        ), health AS (
         SELECT c.partner_id,
            (count(*) FILTER (WHERE (s_1.signal = 'expansion'::text)))::integer AS clients_expansion,
            (count(*) FILTER (WHERE (s_1.signal = 'contraction'::text)))::integer AS clients_contraction,
            (count(*) FILTER (WHERE (s_1.signal = 'stable'::text)))::integer AS clients_stable,
            (count(*) FILTER (WHERE (s_1.signal IS NOT NULL)))::integer AS clients_with_signal
           FROM (public.white_label_clients c
             LEFT JOIN public.v_commercial_lifecycle_signals s_1 ON ((s_1.client_id = c.id)))
          GROUP BY c.partner_id
        )
 SELECT p.id AS partner_id,
    p.partner_slug,
    p.company_name,
    p.tier,
    p.status AS partner_status,
    (date_trunc('month'::text, p.created_at))::date AS cohort_month,
    p.created_at,
    COALESCE(cc.total_clients, 0) AS total_clients,
    COALESCE(cc.active_clients, 0) AS active_clients,
    r.avg_monthly_recurring_usd AS recurring_value_proxy_usd,
    r.sum_recurring_90d_usd,
    r.paid_invoices_90d,
    r.latest_paid_period,
    COALESCE(ac.known_acq_cost_usd, (0)::numeric) AS known_acq_cost_usd,
    COALESCE(ac.commission_events, (0)::bigint) AS commission_events,
    s.servicing_cost_proxy_usd,
    s.servicing_period_start,
    s.servicing_period_end,
        CASE
            WHEN ((r.avg_monthly_recurring_usd IS NOT NULL) AND (s.servicing_cost_proxy_usd IS NOT NULL)) THEN (r.avg_monthly_recurring_usd - s.servicing_cost_proxy_usd)
            ELSE NULL::numeric
        END AS partial_margin_proxy_usd,
        CASE
            WHEN ((r.avg_monthly_recurring_usd IS NOT NULL) AND (r.avg_monthly_recurring_usd > (0)::numeric) AND (s.servicing_cost_proxy_usd IS NOT NULL)) THEN ((r.avg_monthly_recurring_usd - s.servicing_cost_proxy_usd) / r.avg_monthly_recurring_usd)
            ELSE NULL::numeric
        END AS partial_margin_pct,
    COALESCE(h.clients_expansion, 0) AS clients_expansion,
    COALESCE(h.clients_contraction, 0) AS clients_contraction,
    COALESCE(h.clients_stable, 0) AS clients_stable,
    COALESCE(h.clients_with_signal, 0) AS clients_with_signal,
        CASE
            WHEN ((r.avg_monthly_recurring_usd IS NULL) AND (s.servicing_cost_proxy_usd IS NULL)) THEN 'no_data'::text
            WHEN (r.avg_monthly_recurring_usd IS NULL) THEN 'recurring_unknown'::text
            WHEN (s.servicing_cost_proxy_usd IS NULL) THEN 'servicing_cost_unknown'::text
            ELSE 'partial_ok'::text
        END AS coverage_flag
   FROM (((((public.white_label_partners p
     LEFT JOIN client_counts cc ON ((cc.partner_id = p.id)))
     LEFT JOIN public.v_subscription_wl_recurring r ON ((r.partner_id = p.id)))
     LEFT JOIN acq_cost ac ON ((ac.partner_id = p.id)))
     LEFT JOIN servicing s ON ((s.partner_id = p.id)))
     LEFT JOIN health h ON ((h.partner_id = p.id)));


--
-- Name: VIEW v_wl_partner_economics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_wl_partner_economics IS 'Phase 20: per-partner WL economics. Recurring is a 90d paid-invoice avg proxy (not canonical MRR). Servicing cost from latest wl_partner_usage_summary. Acquisition cost from approved/paid sales_commissions. Partner-side CAC excluded.';


--
-- Name: v_partner_success_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_partner_success_summary WITH (security_invoker='true') AS
 WITH band AS (
         SELECT s.partner_id,
            (count(*))::integer AS account_count,
            (count(*) FILTER (WHERE (s.health_band = 'healthy'::text)))::integer AS healthy_count,
            (count(*) FILTER (WHERE (s.health_band = 'watch'::text)))::integer AS watch_count,
            (count(*) FILTER (WHERE (s.health_band = 'intervention'::text)))::integer AS intervention_count
           FROM public.v_success_account_status s
          WHERE (s.partner_id IS NOT NULL)
          GROUP BY s.partner_id
        )
 SELECT e.partner_id,
    e.partner_slug,
    e.company_name,
    e.tier,
    e.partner_status,
    e.cohort_month,
    e.total_clients,
    e.active_clients,
    e.recurring_value_proxy_usd,
    e.partial_margin_proxy_usd,
    e.partial_margin_pct,
    e.clients_expansion,
    e.clients_contraction,
    COALESCE(b.account_count, 0) AS account_count,
    COALESCE(b.healthy_count, 0) AS healthy_count,
    COALESCE(b.watch_count, 0) AS watch_count,
    COALESCE(b.intervention_count, 0) AS intervention_count,
        CASE
            WHEN (COALESCE(b.account_count, 0) > 0) THEN ((b.healthy_count)::numeric / (b.account_count)::numeric)
            ELSE NULL::numeric
        END AS healthy_share,
        CASE
            WHEN (COALESCE(b.account_count, 0) > 0) THEN ((b.intervention_count)::numeric / (b.account_count)::numeric)
            ELSE NULL::numeric
        END AS intervention_share,
    (e.partner_status = 'inactive'::text) AS flag_partner_inactive,
    ((COALESCE(b.intervention_count, 0) > 0) AND (COALESCE(b.account_count, 0) > 0) AND (((b.intervention_count)::numeric / (b.account_count)::numeric) >= 0.3)) AS flag_high_intervention,
    ((e.clients_contraction > e.clients_expansion) AND (e.clients_contraction > 0)) AS flag_net_contraction,
    ((e.partial_margin_pct IS NOT NULL) AND (e.partial_margin_pct < 0.10)) AS flag_low_margin,
    ((COALESCE(b.healthy_count, 0) >= 3) AND (e.clients_expansion >= 2) AND (COALESCE(b.intervention_count, 0) = 0)) AS flag_expansion_ready,
    ((e.active_clients >= 5) AND (((COALESCE(b.healthy_count, 0))::numeric / (NULLIF(b.account_count, 0))::numeric) >= 0.7)) AS flag_strategic,
        CASE
            WHEN (e.partner_status = 'inactive'::text) THEN 'at_risk'::text
            WHEN ((COALESCE(b.intervention_count, 0) > 0) AND (((b.intervention_count)::numeric / (NULLIF(b.account_count, 0))::numeric) >= 0.3)) THEN 'at_risk'::text
            WHEN (((e.clients_contraction > e.clients_expansion) AND (e.clients_contraction > 0)) OR ((e.partial_margin_pct IS NOT NULL) AND (e.partial_margin_pct < 0.10))) THEN 'stabilize'::text
            WHEN ((COALESCE(b.healthy_count, 0) >= 3) AND (e.clients_expansion >= 2) AND (COALESCE(b.intervention_count, 0) = 0) AND (e.active_clients >= 5) AND (((b.healthy_count)::numeric / (NULLIF(b.account_count, 0))::numeric) >= 0.7)) THEN 'strategic_growth'::text
            ELSE 'nurture'::text
        END AS partner_state
   FROM (public.v_wl_partner_economics e
     LEFT JOIN band b ON ((b.partner_id = e.partner_id)));


--
-- Name: VIEW v_partner_success_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_partner_success_summary IS 'Phase 29: per-partner success state with explainable flags. Sources v_wl_partner_economics + v_success_account_status.';


--
-- Name: v_partner_success_opportunities; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_partner_success_opportunities WITH (security_invoker='true') AS
 SELECT s.partner_id,
    s.partner_slug,
    s.company_name,
    s.partner_state,
    'save'::text AS opportunity_type,
    1 AS priority,
    'Net contraction across portfolio'::text AS reason
   FROM public.v_partner_success_summary s
  WHERE s.flag_net_contraction
UNION ALL
 SELECT s.partner_id,
    s.partner_slug,
    s.company_name,
    s.partner_state,
    'save'::text AS opportunity_type,
    1 AS priority,
    'High intervention share (>=30% of accounts)'::text AS reason
   FROM public.v_partner_success_summary s
  WHERE s.flag_high_intervention
UNION ALL
 SELECT s.partner_id,
    s.partner_slug,
    s.company_name,
    s.partner_state,
    'save'::text AS opportunity_type,
    2 AS priority,
    'Partner status inactive'::text AS reason
   FROM public.v_partner_success_summary s
  WHERE s.flag_partner_inactive
UNION ALL
 SELECT s.partner_id,
    s.partner_slug,
    s.company_name,
    s.partner_state,
    'educate'::text AS opportunity_type,
    2 AS priority,
    'Partial margin below 10%'::text AS reason
   FROM public.v_partner_success_summary s
  WHERE (s.flag_low_margin AND (NOT s.flag_high_intervention))
UNION ALL
 SELECT s.partner_id,
    s.partner_slug,
    s.company_name,
    s.partner_state,
    'upsell'::text AS opportunity_type,
    1 AS priority,
    'Healthy portfolio with expansion signals'::text AS reason
   FROM public.v_partner_success_summary s
  WHERE s.flag_expansion_ready
UNION ALL
 SELECT s.partner_id,
    s.partner_slug,
    s.company_name,
    s.partner_state,
    'upsell'::text AS opportunity_type,
    2 AS priority,
    'Strategic growth profile (>=70% healthy, 5+ active clients)'::text AS reason
   FROM public.v_partner_success_summary s
  WHERE (s.flag_strategic AND (NOT s.flag_expansion_ready))
UNION ALL
 SELECT s.partner_id,
    s.partner_slug,
    s.company_name,
    s.partner_state,
    'onboard'::text AS opportunity_type,
    3 AS priority,
    'Has accounts but few healthy clients'::text AS reason
   FROM public.v_partner_success_summary s
  WHERE ((s.healthy_share IS NOT NULL) AND (s.healthy_share < 0.5) AND (s.account_count >= 2) AND (NOT s.flag_high_intervention));


