    fva.pct_variance_churn,
    fva.pct_variance_expansion
   FROM (public.revops_period_snapshots s
     LEFT JOIN public.v_forecast_vs_actuals fva ON (((fva.snapshot_id = s.linked_forecast_snapshot_id) AND (fva.month_start = (date_trunc('month'::text, (s.period_start_date)::timestamp with time zone))::date))));


