--
-- Name: v_subscription_direct_vs_wl; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_subscription_direct_vs_wl WITH (security_invoker='true') AS
 SELECT 'direct'::text AS stream,
    (count(*) FILTER (WHERE (s.subscription_state = 'active'::text)))::integer AS active_subscriptions,
    (count(*) FILTER (WHERE (s.subscription_state = 'canceled'::text)))::integer AS canceled_subscriptions,
    COALESCE(sum(s.mrr_usd) FILTER (WHERE (s.subscription_state = 'active'::text)), (0)::numeric) AS known_mrr_usd,
    NULL::numeric AS recurring_proxy_usd,
    'snapshot_known_mrr'::text AS basis
   FROM public.v_subscription_snapshot s
  WHERE (s.acquisition_type = 'direct'::text)
UNION ALL
 SELECT 'wl'::text AS stream,
    ( SELECT (count(*) FILTER (WHERE (v_subscription_snapshot.subscription_state = 'active'::text)))::integer AS count
           FROM public.v_subscription_snapshot
          WHERE (v_subscription_snapshot.acquisition_type = 'wl'::text)) AS active_subscriptions,
    ( SELECT (count(*) FILTER (WHERE (v_subscription_snapshot.subscription_state = 'canceled'::text)))::integer AS count
           FROM public.v_subscription_snapshot
          WHERE (v_subscription_snapshot.acquisition_type = 'wl'::text)) AS canceled_subscriptions,
    NULL::numeric AS known_mrr_usd,
    COALESCE(sum(w.avg_monthly_recurring_usd), (0)::numeric) AS recurring_proxy_usd,
    'wl_invoices_trailing_90d_avg'::text AS basis
   FROM public.v_subscription_wl_recurring w;


