-- Name: v_bi_subscription_direct_vs_wl; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_subscription_direct_vs_wl WITH (security_invoker='true') AS
 SELECT stream,
    active_subscriptions,
    canceled_subscriptions,
    known_mrr_usd,
    recurring_proxy_usd,
    basis
   FROM public.v_subscription_direct_vs_wl;


