CREATE VIEW public.v_success_direct_vs_wl WITH (security_invoker='true') AS
 SELECT acquisition_type,
    (count(*))::integer AS accounts,
    (count(*) FILTER (WHERE (health_band = 'healthy'::text)))::integer AS healthy,
    (count(*) FILTER (WHERE (health_band = 'watch'::text)))::integer AS watch,
    (count(*) FILTER (WHERE (health_band = 'intervention'::text)))::integer AS intervention,
    (count(*) FILTER (WHERE (lifecycle_signal = 'expansion'::text)))::integer AS expansion_ready,
    (count(*) FILTER (WHERE ('no_live_receptionist'::text = ANY (reasons))))::integer AS no_live_receptionist,
    round(avg(days_live), 1) AS avg_days_live,
    round(avg(days_since_activity), 1) AS avg_days_since_activity
   FROM public.v_success_account_status
  GROUP BY acquisition_type;


