   FROM public.v_success_risk_buckets;


--
-- Name: v_unit_econ_lead_cost; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unit_econ_lead_cost WITH (security_invoker='true') AS
 SELECT l.id AS lead_id,
    COALESCE(sum(sc.commission_amount) FILTER (WHERE (sc.status = ANY (ARRAY['approved'::text, 'paid'::text]))), (0)::numeric) AS known_acq_cost_usd,
    count(sc.id) FILTER (WHERE (sc.status = ANY (ARRAY['approved'::text, 'paid'::text]))) AS commission_events,
        CASE
            WHEN (count(sc.id) FILTER (WHERE (sc.status = ANY (ARRAY['approved'::text, 'paid'::text]))) > 0) THEN 'sales_commissions'::text
            ELSE 'unknown'::text
        END AS cost_basis
   FROM (public.leads l
     LEFT JOIN public.sales_commissions sc ON ((sc.lead_id = l.id)))
  GROUP BY l.id;


--
-- Name: VIEW v_unit_econ_lead_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_unit_econ_lead_cost IS 'Phase 19: per-lead acquisition cost proxy from approved/paid sales commissions. cost_basis=unknown means we have no recorded cost.';


--
-- Name: v_unit_econ_channel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unit_econ_channel WITH (security_invoker='true') AS
 WITH attr AS (
         SELECT a.channel,
            a.lead_id,
            a.converted,
            a.acquisition_type
           FROM public.v_growth_attribution_lead a
        ), costs AS (
         SELECT a.channel,
            sum(c_1.known_acq_cost_usd) AS total_known_cost_usd,
            count(*) FILTER (WHERE (c_1.commission_events > 0)) AS leads_with_known_cost,
            count(*) FILTER (WHERE ((c_1.commission_events > 0) AND a.converted)) AS conversions_with_known_cost,
            count(*) FILTER (WHERE a.converted) AS conversions_total
           FROM (attr a
             JOIN public.v_unit_econ_lead_cost c_1 ON ((c_1.lead_id = a.lead_id)))
          GROUP BY a.channel
        ), mrr AS (
         SELECT a.channel,
            avg(s.mrr_usd) FILTER (WHERE (s.mrr_usd IS NOT NULL)) AS avg_known_mrr_usd,
            count(*) FILTER (WHERE (s.mrr_usd IS NOT NULL)) AS subs_with_known_mrr
           FROM (attr a
             JOIN public.v_subscription_snapshot s ON ((s.lead_id = a.lead_id)))
          GROUP BY a.channel
        ), life AS (
         SELECT a.channel,
            (avg(ce.lifetime_days) / 30.0) AS avg_lifetime_months,
            count(*) AS churn_events
           FROM (attr a
             JOIN public.v_subscription_churn_events ce ON ((ce.lead_id = a.lead_id)))
          GROUP BY a.channel
        )
 SELECT c.channel,
    c.conversions_total,
    c.conversions_with_known_cost,
    c.total_known_cost_usd,
        CASE
            WHEN (c.conversions_with_known_cost > 0) THEN (c.total_known_cost_usd / (c.conversions_with_known_cost)::numeric)
            ELSE NULL::numeric
        END AS cac_usd,
    m.avg_known_mrr_usd,
    m.subs_with_known_mrr,
        CASE
            WHEN (l.churn_events >= 3) THEN l.avg_lifetime_months
            ELSE NULL::numeric
        END AS avg_lifetime_months,
    l.churn_events,
        CASE
            WHEN ((m.avg_known_mrr_usd IS NOT NULL) AND (l.churn_events >= 3)) THEN (m.avg_known_mrr_usd * l.avg_lifetime_months)
            ELSE NULL::numeric
        END AS ltv_usd,
        CASE
            WHEN ((c.conversions_with_known_cost > 0) AND (m.avg_known_mrr_usd IS NOT NULL) AND (m.avg_known_mrr_usd > (0)::numeric)) THEN ((c.total_known_cost_usd / (c.conversions_with_known_cost)::numeric) / m.avg_known_mrr_usd)
            ELSE NULL::numeric
        END AS payback_months,
        CASE
            WHEN (c.conversions_with_known_cost = 0) THEN 'cost_unknown'::text
            WHEN (m.avg_known_mrr_usd IS NULL) THEN 'mrr_unknown'::text
            WHEN (l.churn_events < 3) THEN 'lifetime_insufficient'::text
            ELSE 'ok'::text
        END AS coverage_flag
   FROM ((costs c
     LEFT JOIN mrr m ON ((m.channel = c.channel)))
     LEFT JOIN life l ON ((l.channel = c.channel)));


--
-- Name: VIEW v_unit_econ_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_unit_econ_channel IS 'Phase 19: CAC/LTV/Payback per growth channel. CAC uses commission proxy only. LTV requires >=3 observed churn events in channel. Payback in months.';


--
-- Name: v_bi_unit_econ_channel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_unit_econ_channel WITH (security_invoker='true') AS
 SELECT channel,
    conversions_total,
    conversions_with_known_cost,
    total_known_cost_usd,
    cac_usd,
    avg_known_mrr_usd,
    subs_with_known_mrr,
    avg_lifetime_months,
    churn_events,
    ltv_usd,
    payback_months,
    coverage_flag
   FROM public.v_unit_econ_channel;


--
-- Name: v_unit_econ_cohort; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unit_econ_cohort WITH (security_invoker='true') AS
 WITH attr AS (
         SELECT v_growth_attribution_lead.cohort_month,
            v_growth_attribution_lead.lead_id,
            v_growth_attribution_lead.converted
           FROM public.v_growth_attribution_lead
        ), costs AS (
         SELECT a.cohort_month,
            sum(c_1.known_acq_cost_usd) AS total_known_cost_usd,
            count(*) FILTER (WHERE ((c_1.commission_events > 0) AND a.converted)) AS conversions_with_known_cost,
            count(*) FILTER (WHERE a.converted) AS conversions_total
           FROM (attr a
             JOIN public.v_unit_econ_lead_cost c_1 ON ((c_1.lead_id = a.lead_id)))
          GROUP BY a.cohort_month
        ), mrr AS (
         SELECT a.cohort_month,
            avg(s.mrr_usd) FILTER (WHERE (s.mrr_usd IS NOT NULL)) AS avg_known_mrr_usd
           FROM (attr a
             JOIN public.v_subscription_snapshot s ON ((s.lead_id = a.lead_id)))
          GROUP BY a.cohort_month
        )
 SELECT c.cohort_month,
    c.conversions_total,
    c.conversions_with_known_cost,
    c.total_known_cost_usd,
        CASE
            WHEN (c.conversions_with_known_cost > 0) THEN (c.total_known_cost_usd / (c.conversions_with_known_cost)::numeric)
            ELSE NULL::numeric
        END AS cac_usd,
    m.avg_known_mrr_usd,
        CASE
            WHEN ((c.conversions_with_known_cost > 0) AND (m.avg_known_mrr_usd > (0)::numeric)) THEN ((c.total_known_cost_usd / (c.conversions_with_known_cost)::numeric) / m.avg_known_mrr_usd)
            ELSE NULL::numeric
        END AS payback_months
   FROM (costs c
     LEFT JOIN mrr m ON ((m.cohort_month = c.cohort_month)))
  ORDER BY c.cohort_month DESC;


