--
-- Name: v_unit_econ_direct_vs_wl; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unit_econ_direct_vs_wl WITH (security_invoker='true') AS
 WITH attr AS (
         SELECT v_growth_attribution_lead.acquisition_type,
            v_growth_attribution_lead.lead_id,
            v_growth_attribution_lead.converted
           FROM public.v_growth_attribution_lead
        ), costs AS (
         SELECT a.acquisition_type,
            sum(c_1.known_acq_cost_usd) AS total_known_cost_usd,
            count(*) FILTER (WHERE ((c_1.commission_events > 0) AND a.converted)) AS conversions_with_known_cost,
            count(*) FILTER (WHERE a.converted) AS conversions_total
           FROM (attr a
             JOIN public.v_unit_econ_lead_cost c_1 ON ((c_1.lead_id = a.lead_id)))
          GROUP BY a.acquisition_type
        ), mrr AS (
         SELECT a.acquisition_type,
            avg(s.mrr_usd) FILTER (WHERE (s.mrr_usd IS NOT NULL)) AS avg_known_mrr_usd,
            count(*) FILTER (WHERE (s.mrr_usd IS NOT NULL)) AS subs_with_known_mrr
           FROM (attr a
             JOIN public.v_subscription_snapshot s ON ((s.lead_id = a.lead_id)))
          GROUP BY a.acquisition_type
        ), life AS (
         SELECT a.acquisition_type,
            (avg(ce.lifetime_days) / 30.0) AS avg_lifetime_months,
            count(*) AS churn_events
           FROM (attr a
             JOIN public.v_subscription_churn_events ce ON ((ce.lead_id = a.lead_id)))
          GROUP BY a.acquisition_type
        )
 SELECT c.acquisition_type,
    c.conversions_total,
    c.conversions_with_known_cost,
    c.total_known_cost_usd,
        CASE
            WHEN (c.conversions_with_known_cost > 0) THEN (c.total_known_cost_usd / (c.conversions_with_known_cost)::numeric)
            ELSE NULL::numeric
        END AS cac_usd,
    m.avg_known_mrr_usd,
    m.subs_with_known_mrr,
        CASE
            WHEN (l.churn_events >= 3) THEN l.avg_lifetime_months
            ELSE NULL::numeric
        END AS avg_lifetime_months,
    l.churn_events,
        CASE
            WHEN ((m.avg_known_mrr_usd IS NOT NULL) AND (l.churn_events >= 3)) THEN (m.avg_known_mrr_usd * l.avg_lifetime_months)
            ELSE NULL::numeric
        END AS ltv_usd,
        CASE
            WHEN ((c.conversions_with_known_cost > 0) AND (m.avg_known_mrr_usd > (0)::numeric)) THEN ((c.total_known_cost_usd / (c.conversions_with_known_cost)::numeric) / m.avg_known_mrr_usd)
            ELSE NULL::numeric
        END AS payback_months,
        CASE
            WHEN (c.conversions_with_known_cost = 0) THEN 'cost_unknown'::text
            WHEN (m.avg_known_mrr_usd IS NULL) THEN 'mrr_unknown'::text
            WHEN (l.churn_events < 3) THEN 'lifetime_insufficient'::text
            ELSE 'ok'::text
        END AS coverage_flag,
    'WL acquisition cost is approximated by sales commissions only; partner-side cost not modeled.'::text AS note
   FROM ((costs c
     LEFT JOIN mrr m ON ((m.acquisition_type = c.acquisition_type)))
     LEFT JOIN life l ON ((l.acquisition_type = c.acquisition_type)));


