-- Name: v_wl_partner_cohort_economics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_wl_partner_cohort_economics WITH (security_invoker='true') AS
 SELECT cohort_month,
    (count(*))::integer AS partners_in_cohort,
    (count(*) FILTER (WHERE (partner_status = 'active'::text)))::integer AS active_partners,
    (sum(total_clients))::integer AS total_clients,
    (sum(active_clients))::integer AS active_clients,
    avg(active_clients) AS avg_active_clients_per_partner,
    avg(recurring_value_proxy_usd) FILTER (WHERE (recurring_value_proxy_usd IS NOT NULL)) AS avg_recurring_value_proxy_usd,
    sum(recurring_value_proxy_usd) FILTER (WHERE (recurring_value_proxy_usd IS NOT NULL)) AS sum_recurring_value_proxy_usd,
    sum(known_acq_cost_usd) AS sum_known_acq_cost_usd,
    avg(servicing_cost_proxy_usd) FILTER (WHERE (servicing_cost_proxy_usd IS NOT NULL)) AS avg_servicing_cost_proxy_usd,
    avg(partial_margin_pct) FILTER (WHERE (partial_margin_pct IS NOT NULL)) AS avg_partial_margin_pct,
    (count(*) FILTER (WHERE (coverage_flag = 'partial_ok'::text)))::integer AS partners_with_full_coverage
   FROM public.v_wl_partner_economics
  GROUP BY cohort_month
  ORDER BY cohort_month DESC;


