--
-- Name: v_wl_recurring_vs_internal_cost; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_wl_recurring_vs_internal_cost WITH (security_invoker='true') AS
 SELECT (count(*))::integer AS partners_total,
    (count(*) FILTER (WHERE (partner_status = 'active'::text)))::integer AS partners_active,
    (sum(active_clients))::integer AS active_clients_total,
    sum(recurring_value_proxy_usd) FILTER (WHERE (recurring_value_proxy_usd IS NOT NULL)) AS sum_recurring_value_proxy_usd,
    sum(servicing_cost_proxy_usd) FILTER (WHERE (servicing_cost_proxy_usd IS NOT NULL)) AS sum_servicing_cost_proxy_usd,
    sum(known_acq_cost_usd) AS sum_known_acq_cost_usd,
        CASE
            WHEN ((sum(recurring_value_proxy_usd) FILTER (WHERE (recurring_value_proxy_usd IS NOT NULL)) IS NOT NULL) AND (sum(servicing_cost_proxy_usd) FILTER (WHERE (servicing_cost_proxy_usd IS NOT NULL)) IS NOT NULL)) THEN (sum(recurring_value_proxy_usd) FILTER (WHERE (recurring_value_proxy_usd IS NOT NULL)) - sum(servicing_cost_proxy_usd) FILTER (WHERE (servicing_cost_proxy_usd IS NOT NULL)))
            ELSE NULL::numeric
        END AS sum_partial_margin_proxy_usd,
    (count(*) FILTER (WHERE (coverage_flag = 'partial_ok'::text)))::integer AS partners_with_full_coverage,
    (count(*) FILTER (WHERE (coverage_flag = 'recurring_unknown'::text)))::integer AS partners_recurring_unknown,
    (count(*) FILTER (WHERE (coverage_flag = 'servicing_cost_unknown'::text)))::integer AS partners_servicing_cost_unknown,
    (count(*) FILTER (WHERE (coverage_flag = 'no_data'::text)))::integer AS partners_no_data
   FROM public.v_wl_partner_economics;


--
-- Name: VIEW v_wl_recurring_vs_internal_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_wl_recurring_vs_internal_cost IS 'Phase 20: aggregate WL recurring proxy vs known internal cost signals.';


--
-- Name: v_bi_wl_recurring_vs_internal_cost; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bi_wl_recurring_vs_internal_cost WITH (security_invoker='true') AS
 SELECT partners_total,
    partners_active,
    active_clients_total,
    sum_recurring_value_proxy_usd,
    sum_servicing_cost_proxy_usd,
    sum_known_acq_cost_usd,
    sum_partial_margin_proxy_usd,
    partners_with_full_coverage,
    partners_recurring_unknown,
    partners_servicing_cost_unknown,
    partners_no_data
   FROM public.v_wl_recurring_vs_internal_cost;


--
-- Name: v_campaign_call_attribution; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_campaign_call_attribution WITH (security_invoker='true') AS
 SELECT c.id AS campaign_id,
    c.tenant_kind,
    c.client_lead_id,
    c.wl_partner_id,
    c.wl_client_id,
    c.client_department_id,
    cl.id AS call_id,
    cl.disposition,
    cl.handle_time_seconds,
    cl.call_duration,
    cl.call_date,
    cl.call_time,
    cl.campaign_name AS source_campaign_name,
    cl.dnis
   FROM ((public.call_logs cl
     JOIN public.client_report_mappings m ON (((m.is_active = true) AND (((m.match_type = 'dnis'::text) AND (cl.dnis = m.match_value)) OR ((m.match_type = 'campaign_name'::text) AND (cl.campaign_name = m.match_value)) OR ((m.match_type = 'caller_number'::text) AND (cl.caller_number = m.match_value))))))
     JOIN public.campaigns c ON ((((m.lead_id IS NOT NULL) AND (c.client_lead_id = m.lead_id)) OR ((m.wl_client_id IS NOT NULL) AND (c.wl_client_id = m.wl_client_id)))));


--
-- Name: v_campaign_rollup_30d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_campaign_rollup_30d WITH (security_invoker='true') AS
 SELECT campaign_id,
    tenant_kind,
    client_lead_id,
    wl_partner_id,
    wl_client_id,
    client_department_id,
    (count(*))::integer AS calls_30d,
    (COALESCE(avg(NULLIF(handle_time_seconds, 0)), (0)::numeric))::numeric(10,2) AS avg_handle_time_seconds,
    ((((count(*) FILTER (WHERE (lower(COALESCE(disposition, ''::text)) ~ '(missed|no answer|no-answer|abandon|voicemail|hang)'::text)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric))::numeric(5,2) AS missed_pct,
    max(call_date) AS last_call_date
   FROM public.v_campaign_call_attribution a
  WHERE (call_date >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY campaign_id, tenant_kind, client_lead_id, wl_partner_id, wl_client_id, client_department_id;


--
-- Name: v_candidate_faqs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_candidate_faqs WITH (security_invoker='true') AS
 SELECT id,
    tenant_kind,
    wl_partner_id,
    client_lead_id,
    wl_client_id,
    scope,
    client_department_id,
    client_location_id,
    question,
    answer_md,
    tags,
    status,
    version,
    effective_from,
    effective_to,
    published_at,
    published_by,
    created_at,
    updated_at,
    created_by,
        CASE scope
            WHEN 'call_flow'::text THEN 5
            WHEN 'department'::text THEN 5
            WHEN 'location'::text THEN 4
            WHEN 'client'::text THEN 3
            WHEN 'tenant'::text THEN 2
            ELSE 1
        END AS precedence_rank
   FROM public.campaign_faq_entries f
  WHERE (status = 'approved'::text);


--
-- Name: v_candidate_policies; Type: VIEW; Schema: public; Owner: -
