--
-- Name: v_communication_actions_open; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_communication_actions_open WITH (security_invoker='true') AS
 SELECT a.id,
    a.scope,
    a.target_id,
    a.template_id,
    a.play_id,
    a.channel,
    a.status,
    a.suppression_reason,
    a.rendered_subject,
    a.created_at,
    a.updated_at,
    t.template_key,
    t.sequence_key,
    t.step_number,
    t.play_type,
    t.subject AS template_subject,
    t.requires_approval,
    t.auto_send
   FROM (public.communication_actions a
     JOIN public.communication_templates t ON ((t.id = a.template_id)))
  WHERE (a.status = ANY (ARRAY['suggested'::text, 'approved'::text, 'queued'::text, 'suppressed'::text, 'failed'::text]));


--
-- Name: v_deal_approval_timeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_deal_approval_timeline AS
 SELECT r.id,
    r.deal_id,
    r.policy_id,
    p.name AS policy_name,
    r.required_role,
    r.tier,
    (r.status)::text AS status,
    r.reason,
    r.decision_notes,
    r.decided_by,
    prof.full_name AS decided_by_name,
    r.decided_at,
    r.requested_at,
    r.created_at,
    r.updated_at,
    r.sla_hours_snapshot,
    r.created_notified_at,
    r.sla_notified_at,
    r.estimated_discount_pct_snapshot,
    r.is_non_standard_term_snapshot,
    r.is_exception_snapshot,
    r.proposed_plan_key_snapshot,
    r.proposed_term_months_snapshot,
        CASE
            WHEN (r.decided_at IS NOT NULL) THEN (EXTRACT(epoch FROM (r.decided_at - r.requested_at)) / 3600.0)
            ELSE NULL::numeric
        END AS hours_to_decision,
        CASE
            WHEN (r.status = 'pending'::public.approval_request_status) THEN (EXTRACT(epoch FROM (now() - r.requested_at)) / 3600.0)
            ELSE NULL::numeric
        END AS hours_pending,
        CASE
            WHEN ((r.status = 'pending'::public.approval_request_status) AND (r.sla_hours_snapshot IS NOT NULL) AND ((r.requested_at + ((r.sla_hours_snapshot || ' hours'::text))::interval) < now())) THEN true
            ELSE false
        END AS is_sla_breached
   FROM ((public.approval_requests r
     LEFT JOIN public.approval_policies p ON ((p.id = r.policy_id)))
     LEFT JOIN public.profiles prof ON ((prof.id = r.decided_by)));


--
-- Name: v_direct_overdue_plays; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_direct_overdue_plays WITH (security_invoker='true') AS
 SELECT p.id,
