CREATE VIEW public.v_direct_self_success WITH (security_invoker='true') AS
 WITH me AS (
         SELECT leads.id AS lead_id
           FROM public.leads
          WHERE (leads.user_id = auth.uid())
        )
 SELECT lead_id,
    (health_band = 'healthy'::text) AS hint_healthy,
    flag_no_receptionist AS hint_setup_incomplete,
    flag_support_friction AS hint_support_attention,
    flag_expansion_ready AS hint_expansion_ready,
    flag_new_account AS hint_new_account,
    days_live,
