--
-- Name: v_growth_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_growth_overview WITH (security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM public.disc_generated_pages) AS disc_pages_total,
    ( SELECT count(*) AS count
           FROM public.disc_generated_pages
          WHERE (disc_generated_pages.publish_status = 'published'::text)) AS disc_pages_published,
    ( SELECT count(*) AS count
           FROM public.disc_generated_pages
          WHERE (disc_generated_pages.publish_status = 'draft'::text)) AS disc_pages_draft,
    ( SELECT count(*) AS count
           FROM public.disc_generated_pages
          WHERE ((disc_generated_pages.readiness_state = 'approved'::text) AND (disc_generated_pages.publish_status <> 'published'::text))) AS disc_pages_ready_to_publish,
    ( SELECT count(*) AS count
           FROM public.disc_generated_pages
          WHERE (disc_generated_pages.readiness_state = 'needs_rewrite'::text)) AS disc_pages_needs_rewrite,
    ( SELECT count(*) AS count
           FROM public.disc_templates
          WHERE (disc_templates.status = 'active'::text)) AS disc_templates_active,
    ( SELECT count(*) AS count
           FROM public.disc_keywords
          WHERE (disc_keywords.active = true)) AS disc_keywords_active,
    ( SELECT count(*) AS count
           FROM public.disc_locations
          WHERE (disc_locations.active = true)) AS disc_locations_active,
    ( SELECT count(*) AS count
           FROM public.disc_audiences
          WHERE (disc_audiences.active = true)) AS disc_audiences_active,
    ( SELECT count(*) AS count
           FROM public.blog_posts
          WHERE (blog_posts.status = 'published'::text)) AS blog_posts_published,
    ( SELECT count(*) AS count
           FROM public.blog_posts
          WHERE (blog_posts.status = 'draft'::text)) AS blog_posts_draft,
    ( SELECT count(*) AS count
           FROM public.blog_posts) AS blog_posts_total,
    ( SELECT count(*) AS count
           FROM public.keyword_tracker) AS keywords_tracked;


