-- Name: v_intake_pipeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_intake_pipeline WITH (security_invoker='true') AS
 SELECT i.id,
    i.intake_number,
    i.source,
    i.status,
    i.priority,
    i.partner_id,
    i.client_lead_id,
    i.submitted_by,
    i.submitted_at,
    i.received_at,
    i.approved_at,
    i.activated_at,
    i.closed_at,
    i.assigned_to,
    (EXTRACT(epoch FROM (now() - i.submitted_at)) / 3600.0) AS age_hours,
    l.name AS lead_name,
    l.email AS lead_email,
    p.company_name AS partner_name
   FROM ((public.internal_fulfillment_intakes i
     LEFT JOIN public.leads l ON ((l.id = i.client_lead_id)))
     LEFT JOIN public.white_label_partners p ON ((p.id = i.partner_id)));


