COMMENT ON VIEW public.v_intake_pipeline IS 'Phase 1: fulfillment intake pipeline (24H + WL).';


--
-- Name: v_intelligence_event_trend_30d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_intelligence_event_trend_30d AS
 SELECT (date_trunc('day'::text, occurred_at))::date AS day,
    public.classify_event_domain(event_name) AS domain,
    count(*) AS event_count
   FROM public.dashboard_events
  WHERE (occurred_at >= (now() - '30 days'::interval))
  GROUP BY ((date_trunc('day'::text, occurred_at))::date), (public.classify_event_domain(event_name))
  ORDER BY ((date_trunc('day'::text, occurred_at))::date), (public.classify_event_domain(event_name));


--
-- Name: v_lifecycle_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_lifecycle_overview WITH (security_invoker='true') AS
 SELECT id AS lead_id,
    name,
    email,
    company,
    COALESCE(source, 'unknown'::text) AS source,
    pipeline_stage,
    lead_temperature,
    score,
    assigned_sales_rep,
    assigned_onboarding_rep,
    country,
    billing_currency,
    service_type,
    created_at AS lead_created_at,
    (EXISTS ( SELECT 1
           FROM public.lead_conversions c
          WHERE (c.lead_id = l.id))) AS converted,
    ( SELECT max(c.converted_at) AS max
           FROM public.lead_conversions c
          WHERE (c.lead_id = l.id)) AS converted_at,
    ( SELECT i.status
           FROM public.internal_fulfillment_intakes i
          WHERE (i.client_lead_id = l.id)
          ORDER BY i.submitted_at DESC
         LIMIT 1) AS intake_status,
    ( SELECT i.id
           FROM public.internal_fulfillment_intakes i
          WHERE (i.client_lead_id = l.id)
          ORDER BY i.submitted_at DESC
         LIMIT 1) AS intake_id,
    ( SELECT count(*) AS count
           FROM public.campaigns ca
          WHERE (ca.client_lead_id = l.id)) AS campaigns_count,
    ( SELECT count(*) AS count
           FROM public.campaigns ca
          WHERE ((ca.client_lead_id = l.id) AND (ca.status = 'active'::text))) AS active_campaigns,
    ( SELECT max(cl.created_at) AS max
           FROM public.call_logs cl
          WHERE (cl.client_id = l.id)) AS last_call_at,
    last_payment_status,
    payment_failure_count
   FROM public.leads l;


