-- Name: v_open_approval_requests; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_open_approval_requests WITH (security_invoker='true') AS
 SELECT ar.id,
    ar.deal_id,
    ar.policy_id,
    ar.required_role,
    ar.tier,
    ar.reason,
    ar.requested_at,
    ar.created_at,
    d.scope,
    d.deal_type,
    d.target_id,
    d.stage,
    d.approval_state,
    d.estimated_discount_pct,
    d.is_non_standard_term,
    d.is_exception,
    d.proposed_plan_key,
    d.proposed_term_months,
    d.proposed_price_summary,
    p.name AS policy_name,
    (EXTRACT(epoch FROM (now() - ar.requested_at)) / (3600)::numeric) AS hours_pending
   FROM ((public.approval_requests ar
     JOIN public.renewal_expansion_deals d ON ((d.id = ar.deal_id)))
     LEFT JOIN public.approval_policies p ON ((p.id = ar.policy_id)))
