--
-- Name: v_open_deals_pipeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_open_deals_pipeline WITH (security_invoker='true') AS
 SELECT d.id,
    d.scope,
    d.target_id,
    d.deal_type,
    d.related_renewal_workflow_id,
    d.related_partner_play_id,
    d.related_direct_play_id,
    d.owner_user_id,
    d.current_plan_key,
    d.current_subscription_id,
    d.proposed_plan_key,
    d.proposed_offer_id,
    d.proposed_term_months,
    d.proposed_price_summary,
    d.stage,
    d.status,
    d.outcome_reason,
    d.expected_close_date,
    d.implemented_at,
    d.notes,
    d.stage_changed_at,
    d.created_by,
    d.created_at,
    d.updated_at,
        CASE
            WHEN (d.expected_close_date IS NOT NULL) THEN (d.expected_close_date - CURRENT_DATE)
            ELSE NULL::integer
        END AS days_to_expected_close,
    (EXTRACT(epoch FROM (now() - d.stage_changed_at)) / 86400.0) AS days_in_stage,
    ( SELECT count(*) AS count
           FROM public.communication_actions ca
          WHERE (ca.deal_id = d.id)) AS comm_action_count,
    rw.renewal_date,
    rw.stage AS renewal_stage
   FROM (public.renewal_expansion_deals d
     LEFT JOIN public.renewal_workflows rw ON ((rw.id = d.related_renewal_workflow_id)))
  WHERE (d.status = 'open'::public.deal_status);


