   FROM ((public.partner_success_plays p
     LEFT JOIN public.white_label_partners wp ON ((wp.id = p.partner_id)))
     LEFT JOIN public.playbook_templates t ON ((t.id = p.template_id)))
  WHERE ((p.status = ANY (ARRAY['not_started'::text, 'active'::text])) AND p.reminder_enabled AND (p.due_date IS NOT NULL) AND (p.due_date <= (CURRENT_DATE + '3 days'::interval)));


--
-- Name: v_partner_self_success; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_partner_self_success WITH (security_invoker='true') AS
 WITH me AS (
         SELECT white_label_partners.id AS partner_id
           FROM public.white_label_partners
          WHERE (white_label_partners.user_id = auth.uid())
        ), band AS (
         SELECT s.partner_id,
            (count(*))::integer AS account_count,
            (count(*) FILTER (WHERE (s.health_band = 'healthy'::text)))::integer AS healthy_count,
            (count(*) FILTER (WHERE (s.health_band = 'watch'::text)))::integer AS watch_count,
            (count(*) FILTER (WHERE (s.health_band = 'intervention'::text)))::integer AS intervention_count
           FROM public.v_success_account_status s
          WHERE (s.partner_id IN ( SELECT me.partner_id
                   FROM me))
          GROUP BY s.partner_id
        ), econ AS (
         SELECT v_wl_partner_economics.partner_id,
            v_wl_partner_economics.clients_expansion,
            v_wl_partner_economics.clients_contraction,
            v_wl_partner_economics.active_clients
           FROM public.v_wl_partner_economics
          WHERE (v_wl_partner_economics.partner_id IN ( SELECT me.partner_id
                   FROM me))
        )
 SELECT m.partner_id,
    COALESCE(b.account_count, 0) AS account_count,
    COALESCE(b.healthy_count, 0) AS healthy_count,
    COALESCE(b.watch_count, 0) AS watch_count,
    COALESCE(b.intervention_count, 0) AS intervention_count,
    COALESCE(e.clients_expansion, 0) AS clients_expansion,
    COALESCE(e.clients_contraction, 0) AS clients_contraction,
    COALESCE(e.active_clients, 0) AS active_clients,
    ((COALESCE(b.healthy_count, 0) >= 3) AND (COALESCE(e.clients_expansion, 0) >= 2) AND (COALESCE(b.intervention_count, 0) = 0)) AS hint_expansion_ready,
    (COALESCE(b.intervention_count, 0) > 0) AS hint_attention_needed,
    ((COALESCE(b.account_count, 0) > 0) AND (((COALESCE(b.healthy_count, 0))::numeric / (b.account_count)::numeric) >= 0.7)) AS hint_strong_portfolio
   FROM ((me m
     LEFT JOIN band b ON ((b.partner_id = m.partner_id)))
     LEFT JOIN econ e ON ((e.partner_id = m.partner_id)));


