COMMENT ON VIEW public.v_partner_success_accounts IS 'Phase 29: per-partner account-level drivers behind partner success state.';


--
-- Name: v_play_suggestions_open; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_play_suggestions_open WITH (security_invoker='true') AS
 SELECT s.id,
    s.scope,
    s.target_id,
    s.template_id,
    s.opportunity_type,
    s.reason,
    s.status,
    s.created_at,
    t.title AS template_title,
    t.play_type AS template_play_type,
    t.default_followup_days,
    t.auto_create,
        CASE
            WHEN (s.scope = 'partner'::text) THEN wp.company_name
            WHEN (s.scope = 'direct'::text) THEN COALESCE(l.company, l.name)
            ELSE NULL::text
        END AS target_label
   FROM (((public.play_suggestions s
     JOIN public.playbook_templates t ON ((t.id = s.template_id)))
     LEFT JOIN public.white_label_partners wp ON (((s.scope = 'partner'::text) AND (wp.id = s.target_id))))
     LEFT JOIN public.leads l ON (((s.scope = 'direct'::text) AND (l.id = s.target_id))))
  WHERE (s.status = 'pending'::text);


--
-- Name: v_renewal_workflows_pipeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_renewal_workflows_pipeline WITH (security_invoker='true') AS
 SELECT id,
    scope,
    target_id,
    subscription_id,
    renewal_date,
    stage,
    outcome_notes,
    last_touch_at,
    created_at,
    updated_at,
    (renewal_date - CURRENT_DATE) AS days_to_renewal
   FROM public.renewal_workflows r;


--
-- Name: v_revenue_lead_360; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_revenue_lead_360 WITH (security_invoker='true') AS
 SELECT id AS lead_id,
    name,
    email,
    company,
    source,
    pipeline_stage,
    lead_temperature,
    assigned_sales_rep,
    qualified_at,
    won_at,
    lost_at,
    (( SELECT count(*) AS count
           FROM public.meetings m
          WHERE (m.lead_id = l.id)))::integer AS meetings_count,
    ( SELECT max(m.scheduled_at) AS max
           FROM public.meetings m
          WHERE (m.lead_id = l.id)) AS latest_meeting_at,
    (( SELECT count(*) AS count
           FROM public.sales_proposals p
          WHERE (p.lead_id = l.id)))::integer AS proposals_count,
    ( SELECT max(p.sent_at) AS max
           FROM public.sales_proposals p
          WHERE (p.lead_id = l.id)) AS latest_proposal_sent_at,
    (EXISTS ( SELECT 1
           FROM public.affiliate_referrals ar
          WHERE (ar.lead_id = l.id))) AS has_affiliate_referral,
    (EXISTS ( SELECT 1
           FROM public.lead_conversions c
          WHERE (c.lead_id = l.id))) AS converted
   FROM public.leads l;


--
-- Name: v_scenario_outcome_rollup; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_scenario_outcome_rollup WITH (security_invoker='true') AS
 WITH scenario_calls AS (
         SELECT s.id AS scenario_id,
            s.campaign_id,
            s.title AS scenario_title,
            public.disposition_bucket(a.disposition) AS bucket,
            a.call_id
           FROM (public.campaign_scenarios s
             LEFT JOIN public.v_campaign_call_attribution a ON (((a.campaign_id = s.campaign_id) AND (a.call_date >= (CURRENT_DATE - '30 days'::interval)))))
        )
 SELECT scenario_id,
    campaign_id,
    scenario_title,
    (count(*) FILTER (WHERE ((bucket = 'resolved'::text) AND (call_id IS NOT NULL))))::integer AS resolved_count,
    (count(*) FILTER (WHERE ((bucket = 'escalated'::text) AND (call_id IS NOT NULL))))::integer AS escalated_count,
    (count(*) FILTER (WHERE ((bucket = 'no_contact'::text) AND (call_id IS NOT NULL))))::integer AS no_contact_count,
    (count(*) FILTER (WHERE ((bucket = 'other'::text) AND (call_id IS NOT NULL))))::integer AS other_count,
    (count(*) FILTER (WHERE (call_id IS NOT NULL)))::integer AS total_count
   FROM scenario_calls
  GROUP BY scenario_id, campaign_id, scenario_title;


--
-- Name: v_stalled_approved_deals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_stalled_approved_deals WITH (security_invoker='true') AS
 SELECT id,
    scope,
    target_id,
    deal_type,
    related_renewal_workflow_id,
    related_partner_play_id,
    related_direct_play_id,
    owner_user_id,
    current_plan_key,
    current_subscription_id,
    proposed_plan_key,
    proposed_offer_id,
    proposed_term_months,
    proposed_price_summary,
    stage,
    status,
    outcome_reason,
    expected_close_date,
    implemented_at,
    notes,
    stage_changed_at,
    created_by,
    created_at,
    updated_at,
    (EXTRACT(epoch FROM (now() - stage_changed_at)) / 86400.0) AS days_since_approval
   FROM public.renewal_expansion_deals d
  WHERE ((stage = 'verbally_approved'::public.deal_stage) AND (status = 'open'::public.deal_status) AND (stage_changed_at < (now() - '14 days'::interval)));


--
-- Name: v_tenant_brand; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_tenant_brand WITH (security_invoker='true') AS
 WITH overrides AS (
         SELECT tbp.tenant_kind,
            tbp.wl_partner_id,
            tbp.client_lead_id,
            tbp.wl_client_id,
            tbp.brand_label,
            tbp.logo_url,
            tbp.primary_color,
            tbp.secondary_color,
            tbp.accent_color,
            tbp.sender_name,
            tbp.sender_email,
            tbp.support_email,
            tbp.support_phone,
            tbp.footer_html,
            tbp.social_links,
            'override'::text AS source
           FROM public.tenant_brand_profiles tbp
        ), wl_brand AS (
         SELECT 'wl_partner'::public.campaign_tenant_kind AS tenant_kind,
            wlb.partner_id AS wl_partner_id,
            NULL::uuid AS client_lead_id,
            NULL::uuid AS wl_client_id,
            wlb.company_name AS brand_label,
            wlb.logo_url,
            wlb.primary_color,
            wlb.secondary_color,
            wlb.accent_color,
            COALESCE(wlb.email_from_name, wlb.company_name) AS sender_name,
            COALESCE(wlb.email_from_address, wlb.support_email) AS sender_email,
            wlb.support_email,
            wlb.support_phone,
            wlb.email_footer AS footer_html,
            '{}'::jsonb AS social_links,
            'wl_branding'::text AS source
           FROM public.white_label_branding wlb
        )
 SELECT overrides.tenant_kind,
    overrides.wl_partner_id,
    overrides.client_lead_id,
    overrides.wl_client_id,
    overrides.brand_label,
    overrides.logo_url,
    overrides.primary_color,
    overrides.secondary_color,
    overrides.accent_color,
    overrides.sender_name,
    overrides.sender_email,
    overrides.support_email,
    overrides.support_phone,
    overrides.footer_html,
    overrides.social_links,
    overrides.source
   FROM overrides
UNION ALL
 SELECT wl_brand.tenant_kind,
    wl_brand.wl_partner_id,
    wl_brand.client_lead_id,
    wl_brand.wl_client_id,
    wl_brand.brand_label,
    wl_brand.logo_url,
    wl_brand.primary_color,
    wl_brand.secondary_color,
    wl_brand.accent_color,
    wl_brand.sender_name,
    wl_brand.sender_email,
    wl_brand.support_email,
    wl_brand.support_phone,
    wl_brand.footer_html,
    wl_brand.social_links,
    wl_brand.source
   FROM wl_brand
  WHERE (NOT (EXISTS ( SELECT 1
           FROM overrides o
          WHERE ((o.tenant_kind = 'wl_partner'::public.campaign_tenant_kind) AND (o.wl_partner_id = wl_brand.wl_partner_id) AND (o.wl_client_id IS NULL)))));


