--
-- Name: v_wl_partner_self_economics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_wl_partner_self_economics WITH (security_invoker='true') AS
 SELECT partner_id,
    partner_slug,
    company_name,
    tier,
    partner_status,
    cohort_month,
    created_at,
    total_clients,
    active_clients,
    recurring_value_proxy_usd,
    sum_recurring_90d_usd,
    paid_invoices_90d,
    latest_paid_period,
    clients_expansion,
    clients_contraction,
    clients_stable,
    clients_with_signal,
        CASE
            WHEN (recurring_value_proxy_usd IS NULL) THEN 'recurring_unknown'::text
            ELSE 'recurring_known'::text
        END AS coverage_flag
   FROM public.v_wl_partner_economics e
  WHERE (EXISTS ( SELECT 1
           FROM public.white_label_partners wlp
          WHERE ((wlp.id = e.partner_id) AND (wlp.user_id = auth.uid()))));


--
-- Name: v_wl_partner_self_portfolio_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_wl_partner_self_portfolio_health WITH (security_invoker='true') AS
 SELECT wlp.id AS partner_id,
    COALESCE(s.health_band, 'unknown'::text) AS health_band,
    count(*) AS client_count
   FROM ((public.white_label_partners wlp
     JOIN public.v_growth_attribution_lead g ON ((g.wl_partner_id = wlp.id)))
     LEFT JOIN public.v_success_account_status s ON ((s.lead_id = g.lead_id)))
  WHERE (wlp.user_id = auth.uid())
  GROUP BY wlp.id, s.health_band;


