--
-- Name: wl_campaign_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.wl_campaign_metrics WITH (security_invoker='on') AS
 SELECT c.id AS campaign_id,
    c.wl_client_id,
    c.partner_id,
    count(r.id) AS total_recipients,
    count(*) FILTER (WHERE (r.status = ANY (ARRAY['sent'::text, 'opened'::text, 'replied'::text, 'converted'::text]))) AS sent_count,
    count(*) FILTER (WHERE (r.status = ANY (ARRAY['opened'::text, 'replied'::text, 'converted'::text]))) AS opened_count,
    count(*) FILTER (WHERE (r.status = ANY (ARRAY['replied'::text, 'converted'::text]))) AS replied_count,
    count(*) FILTER (WHERE (r.status = 'converted'::text)) AS converted_count,
    count(*) FILTER (WHERE (r.status = 'failed'::text)) AS failed_count,
    count(*) FILTER (WHERE (r.status = 'queued'::text)) AS queued_count
   FROM (public.wl_client_campaigns c
     LEFT JOIN public.wl_campaign_recipients r ON ((r.campaign_id = c.id)))
  GROUP BY c.id, c.wl_client_id, c.partner_id;


