--
-- Name: wl_partner_feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wl_partner_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_id uuid NOT NULL,
    origin text NOT NULL,
    submitted_by_type text NOT NULL,
    submitted_by_user_id uuid,
    submitted_by_email text,
    submitted_by_name text,
    type text DEFAULT 'feedback'::text NOT NULL,
    title text,
    description text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    status text DEFAULT 'new'::text NOT NULL,
    source_dashboard text NOT NULL,
    page text,
    attachment_url text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    internal_notes jsonb DEFAULT '[]'::jsonb NOT NULL,
    assigned_to uuid,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT wl_pf_origin_check CHECK ((origin = ANY (ARRAY['end_client'::text, 'partner_on_behalf'::text]))),
    CONSTRAINT wl_pf_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT wl_pf_source_check CHECK ((source_dashboard = ANY (ARRAY['wl_end_client'::text, 'wl_partner'::text]))),
