--
-- Name: v_offer_exposure_summary _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.v_offer_exposure_summary WITH (security_invoker='true') AS
 SELECT o.id AS offer_id,
    o.key AS offer_key,
    o.label,
    o.surface,
    o.audience,
    o.plan_key,
    o.stripe_price_id,
    o.experiment_id,
    o.variant_key,
    o.is_baseline,
    o.active,
    o.partner_id,
    COALESCE(sum(
        CASE
            WHEN (e.event = 'shown'::text) THEN 1
            ELSE 0
        END), (0)::bigint) AS shown_count,
    COALESCE(sum(
        CASE
            WHEN (e.event = 'accepted'::text) THEN 1
            ELSE 0
        END), (0)::bigint) AS accepted_count,
    COALESCE(sum(
        CASE
            WHEN (e.event = 'completed'::text) THEN 1
            ELSE 0
        END), (0)::bigint) AS completed_count,
    COALESCE(sum(
        CASE
            WHEN (e.event = 'rejected'::text) THEN 1
            ELSE 0
        END), (0)::bigint) AS rejected_count,
    max(e.created_at) AS last_exposure_at
   FROM (public.offers o
     LEFT JOIN public.offer_exposures e ON ((e.offer_id = o.id)))
  GROUP BY o.id;


